1	package fleet
2	
3	import (
4		"errors"
5		"sort"
6		"sync"
7		"time"
8	)
9	
10	var (
11		ErrDeviceNotFound  = errors.New("device not found")
12		ErrBatchConflict   = errors.New("batch conflicts with stored events")
13		ErrRuleNotFound    = errors.New("rule not found")
14		ErrAlertNotFound   = errors.New("alert not found")
15		ErrRuleConflict    = errors.New("rule already exists")
16		ErrVersionConflict = errors.New("rule version conflict")
17		ErrInvalidRule     = errors.New("invalid rule")
18	)
19	
20	// Rule is a per-device threshold rule. It judges only samples accepted while
21	// enabled; it never backfills history. Device and ID are immutable after
22	// creation. Version starts at 1 and bumps on every successful update.
23	type Rule struct {
24		ID        string    `json:"id"`
25		Metric    string    `json:"metric"`
26		Trigger   float64   `json:"trigger"`
27		Recover   float64   `json:"recover"`
28		Enabled   bool      `json:"enabled"`
29		Version   int64     `json:"version"`
30		CreatedAt time.Time `json:"createdAt"`
31		UpdatedAt time.Time `json:"updatedAt"`
32	}
33	
34	// Alert is one threshold crossing. It retains the rule version and the
35	// metric/thresholds in force when it fired. A natural recovery records the
36	// recovery sample's sequence, value and observed time; an end caused by a rule
37	// update records the server time and reason instead.
38	type Alert struct {
39		ID                int64      `json:"id"`
40		RuleID            string     `json:"ruleId"`
41		RuleVersion       int64      `json:"ruleVersion"`
42		Metric            string     `json:"metric"`
43		Trigger           float64    `json:"trigger"`
44		Recover           float64    `json:"recover"`
45		Status            string     `json:"status"` // "active" | "ended"
46		TriggerSequence   int64      `json:"triggerSequence"`
47		TriggerValue      float64    `json:"triggerValue"`
48		TriggerObservedAt time.Time  `json:"triggerObservedAt"`
49		RecoverSequence   *int64     `json:"recoverSequence,omitempty"`
50		RecoverValue      *float64   `json:"recoverValue,omitempty"`
51		RecoverObservedAt *time.Time `json:"recoverObservedAt,omitempty"`
52		EndedAt           *time.Time `json:"endedAt,omitempty"`
53		EndReason         string     `json:"endReason,omitempty"` // "recovered" | "rule_changed"
54		AcknowledgedAt    *time.Time `json:"acknowledgedAt,omitempty"`
55	}
56	
57	const (
58		alertStatusActive    = "active"
59		alertStatusEnded     = "ended"
60		endReasonRecovered   = "recovered"
61		endReasonRuleChanged = "rule_changed"
62	)
63	
64	// ruleState pairs a rule with the id of its currently active alert (0 when
65	// none).
66	type ruleState struct {
67		rule          Rule
68		activeAlertID int64
69	}
70	
71	type Device struct {
72		ID            string             `json:"id"`
73		Site          string             `json:"site"`
74		RegisteredAt  time.Time          `json:"registeredAt"`
75		LastSeenAt    time.Time          `json:"lastSeenAt"`
76		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
77	}
78	
79	// Event is a single telemetry sample retained in a device's history.
80	type Event struct {
81		Sequence   int64              `json:"sequence"`
82		ObservedAt time.Time          `json:"observedAt"`
83		Values     map[string]float64 `json:"values"`
84	}
85	
86	// Sample is one replayed sample, decoded from the replay request body.
87	type Sample struct {
88		EventID    string
89		ObservedAt time.Time
90		Values     map[string]float64
91	}
92	
93	// ReplayReceipt summarises the outcome of a replay batch.
94	type ReplayReceipt struct {
95		BatchID      string         `json:"batchId"`
96		NewCount     int            `json:"newCount"`
97		Duplicate    int            `json:"duplicateCount"`
98		SampleStatus []SampleStatus `json:"samples"`
99	}
100	
101	// SampleStatus reports the history sequence assigned to (or reused by) a sample.
102	type SampleStatus struct {
103		EventID   string `json:"eventId"`
104		Sequence  int64  `json:"sequence"`
105		Duplicate bool   `json:"duplicate"`
106	}
107	
108	// HistoryFilter narrows a history query by observed-time range. Zero times mean
109	// the bound is open.
110	type HistoryFilter struct {
111		From time.Time
112		To   time.Time
113	}
114	
115	// StoredBatch records the ordered samples an accepted batchId committed along
116	// with the receipt returned on first acceptance, so a repeated batchId can be
117	// checked for identical content and replayed with the original receipt.
118	type storedBatch struct {
119		samples []Sample
120		receipt ReplayReceipt
121	}
122	
123	type deviceState struct {
124		device  Device
125		events  []Event          // history ordered by sequence (sequence = index + 1)
126		byEvent map[string]int64 // eventId -> sequence
127		batches map[string]storedBatch
128		rules   map[string]*ruleState
129		alerts  []*Alert // per-device, ordered by alert id (id = index + 1)
130		config  *configState
131	}
132	
133	type Store struct {
134		mu      sync.RWMutex
135		devices map[string]*deviceState
136		now     func() time.Time
137	
138		// wal is nil in memory mode. When set, every mutation is appended and
139		// synced here before in-memory state changes or success is returned.
140		wal walSink
141		iid []byte // data-directory instance id bound into history cursors
142	}
143	
144	func NewStore() *Store {
145		return &Store{devices: make(map[string]*deviceState), now: time.Now}
146	}
147	
148	// instanceID identifies the backing data directory; cursors are scoped to it.
149	// It is nil in memory mode.
150	func (s *Store) instanceID() []byte {
151		s.mu.RLock()
152		defer s.mu.RUnlock()
153		return s.iid
154	}
155	
156	// Exists reports whether a device is registered.
157	func (s *Store) Exists(id string) bool {
158		s.mu.RLock()
159		defer s.mu.RUnlock()
160		_, ok := s.devices[id]
161		return ok
162	}
163	
164	func (s *Store) Register(id, site string) (Device, bool, error) {
165		s.mu.Lock()
166		defer s.mu.Unlock()
167		if state, ok := s.devices[id]; ok {
168			return cloneDevice(state.device), false, nil
169		}
170		now := s.now().UTC()
171		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
172		if s.wal != nil {
173			if err := s.wal.appendRecord(recRegister, walRegister{
174				ID: id, Site: site, RegisteredAt: now, LastSeenAt: now,
175			}); err != nil {
176				return Device{}, false, storageUnavailable(err)
177			}
178		}
179		s.devices[id] = &deviceState{
180			device:  device,
181			byEvent: make(map[string]int64),
182			batches: make(map[string]storedBatch),
183			rules:   make(map[string]*ruleState),
184		}
185		return cloneDevice(device), true, nil
186	}
187	
188	// RecordTelemetry stores a live telemetry sample in the device history. The
189	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
190	// observed time is the server receive time.
191	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
192		s.mu.Lock()
193		defer s.mu.Unlock()
194		state, ok := s.devices[id]
195		if !ok {
196			return Device{}, ErrDeviceNotFound
197		}
198		now := s.now().UTC()
199		sequence := int64(len(state.events)) + 1
200		eval := newAlertEvaluator(state)
201		eval.evaluate(sequence, now, values)
202		if s.wal != nil {
203			if err := s.wal.appendRecord(recTelemetry, walTelemetry{
204				DeviceID:   id,
205				Sequence:   sequence,
206				ObservedAt: now,
207				Values:     values,
208				Alerts:     eval.created,
209				Ended:      eval.ended,
210			}); err != nil {
211				return Device{}, storageUnavailable(err)
212			}
213		}
214		state.events = append(state.events, Event{
215			Sequence:   sequence,
216			ObservedAt: now,
217			Values:     cloneTelemetry(values),
218		})
219		state.device.LastSeenAt = now
220		state.device.LastTelemetry = cloneTelemetry(values)
221		eval.commit()
222		return cloneDevice(state.device), nil
223	}
224	
225	// Replay validates and commits a batch atomically. repeat is true when the
226	// batchId was already committed with identical content and the first receipt
227	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
228	// ErrBatchConflict when any sample clashes with an existing eventId or the
229	// batchId was previously committed with different ordered content; in either
230	// conflict case no state changes.
231	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
232		s.mu.Lock()
233		defer s.mu.Unlock()
234		state, ok := s.devices[id]
235		if !ok {
236			return ReplayReceipt{}, false, ErrDeviceNotFound
237		}
238	
239		if previous, exists := state.batches[batchID]; exists {
240			if !sameOrderedSamples(previous.samples, samples) {
241				return ReplayReceipt{}, false, ErrBatchConflict
242			}
243			return cloneReceipt(previous.receipt), true, nil
244		}
245	
246		// Validate every sample against committed history before appending so a
247		// conflict rolls back without leaving sequences, events or receipts.
248		type plan struct {
249			sample   Sample
250			sequence int64
251			dup      bool
252		}
253		planned := make([]plan, len(samples))
254		nextSequence := int64(len(state.events)) + 1
255		for i, sample := range samples {
256			if sequence, seen := state.byEvent[sample.EventID]; seen {
257				existing := state.events[sequence-1]
258				if !sameInstant(existing.ObservedAt, sample.ObservedAt) ||
259					!sameValues(existing.Values, sample.Values) {
260					return ReplayReceipt{}, false, ErrBatchConflict
261				}
262				planned[i] = plan{sample, sequence, true}
263				continue
264			}
265			planned[i] = plan{sample, nextSequence, false}
266			nextSequence++
267		}
268	
269		// Build the receipt from the plan: only samples that matched a committed
270		// event before this batch are duplicates.
271		receipt = ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
272		for _, entry := range planned {
273			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
274				EventID:   entry.sample.EventID,
275				Sequence:  entry.sequence,
276				Duplicate: entry.dup,
277			})
278			if entry.dup {
279				receipt.Duplicate++
280			} else {
281				receipt.NewCount++
282			}
283		}
284	
285		// Evaluate the batch's new samples against the device's enabled rules, in
286		// array order (which is receive-sequence order). Duplicates never judge,
287		// create, end or refresh alerts. A trigger and a recovery inside one batch
288		// both produce alert changes, all committed together with the batch.
289		eval := newAlertEvaluator(state)
290		for _, entry := range planned {
291			if entry.dup {
292				continue
293			}
294			eval.evaluate(entry.sequence, entry.sample.ObservedAt, entry.sample.Values)
295		}
296	
297		// Durable commit point: the whole batch is one record, synced before any
298		// in-memory state changes and before success is reported. A failure here
299		// leaves sequences, history, receipts, device state and alert changes
300		// untouched.
301		lastNew := -1
302		for i, entry := range planned {
303			if !entry.dup {
304				lastNew = i
305			}
306		}
307		var committedAt time.Time
308		if s.wal != nil {
309			record := walReplay{
310				DeviceID: id,
311				BatchID:  batchID,
312				Samples:  make([]walSample, len(samples)),
313				Receipt:  receipt,
314				Alerts:   eval.created,
315				Ended:    eval.ended,
316			}
317			for i, sample := range samples {
318				record.Samples[i] = walSample{
319					EventID:    sample.EventID,
320					ObservedAt: sample.ObservedAt,
321					Values:     sample.Values,
322				}
323			}
324			if lastNew >= 0 {
325				committedAt = s.now().UTC()
326				record.LastSeenAt = &committedAt
327				record.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
328			}
329			if err := s.wal.appendRecord(recReplay, record); err != nil {
330				return ReplayReceipt{}, false, storageUnavailable(err)
331			}
332		}
333	
334		// Commit: append new samples in array order.
335		for _, entry := range planned {
336			if entry.dup {
337				continue
338			}
339			state.events = append(state.events, Event{
340				Sequence:   entry.sequence,
341				ObservedAt: entry.sample.ObservedAt,
342				Values:     cloneTelemetry(entry.sample.Values),
343			})
344			state.byEvent[entry.sample.EventID] = entry.sequence
345		}
346	
347		committed := make([]Sample, len(samples))
348		copy(committed, samples)
349		for i := range committed {
350			committed[i].Values = cloneTelemetry(samples[i].Values)
351		}
352		state.batches[batchID] = storedBatch{samples: committed, receipt: cloneReceipt(receipt)}
353	
354		if lastNew >= 0 {
355			if s.wal == nil {
356				committedAt = s.now().UTC()
357			}
358			state.device.LastSeenAt = committedAt
359			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
360		}
361		eval.commit()
362		return receipt, false, nil
363	}
364	
365	func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
366		receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
367		return receipt
368	}
369	
370	// --- rules and alerts -------------------------------------------------------
371	
372	// ruleUpdate carries the mutable fields of a rule update. A nil pointer leaves
373	// the field unchanged.
374	type ruleUpdate struct {
375		Metric  *string
376		Trigger *float64
377		Recover *float64
378		Enabled *bool
379	}
380	
381	// AlertFilter narrows an alert listing. An empty string or nil pointer leaves
382	// that dimension unfiltered.
383	type AlertFilter struct {
384		RuleID       string
385		Status       string
386		Acknowledged *bool
387	}
388	
389	// CreateRule registers a new enabled rule on a device. Version starts at 1.
390	// It returns ErrDeviceNotFound for an unknown device and ErrRuleConflict when
391	// the device already has a rule with that id.
392	func (s *Store) CreateRule(id, ruleID, metric string, trigger, recover float64) (Rule, error) {
393		s.mu.Lock()
394		defer s.mu.Unlock()
395		state, ok := s.devices[id]
396		if !ok {
397			return Rule{}, ErrDeviceNotFound
398		}
399		if _, exists := state.rules[ruleID]; exists {
400			return Rule{}, ErrRuleConflict
401		}
402		now := s.now().UTC()
403		rule := Rule{
404			ID: ruleID, Metric: metric, Trigger: trigger, Recover: recover,
405			Enabled: true, Version: 1, CreatedAt: now, UpdatedAt: now,
406		}
407		if s.wal != nil {
408			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: rule}); err != nil {
409				return Rule{}, storageUnavailable(err)
410			}
411		}
412		state.rules[ruleID] = &ruleState{rule: rule}
413		return cloneRule(rule), nil
414	}
415	
416	// UpdateRule applies a version-checked optimistic update. A version mismatch
417	// returns ErrVersionConflict with state unchanged. Every successful update
418	// bumps the version by one and immediately ends the rule's active alert (if
419	// any) with reason rule_changed; the rule starts again with no active alert.
420	func (s *Store) UpdateRule(id, ruleID string, update ruleUpdate, version int64) (Rule, []*Alert, error) {
421		s.mu.Lock()
422		defer s.mu.Unlock()
423		state, ok := s.devices[id]
424		if !ok {
425			return Rule{}, nil, ErrDeviceNotFound
426		}
427		rs, ok := state.rules[ruleID]
428		if !ok {
429			return Rule{}, nil, ErrRuleNotFound
430		}
431		if rs.rule.Version != version {
432			return Rule{}, nil, ErrVersionConflict
433		}
434	
435		updated := rs.rule
436		if update.Metric != nil {
437			updated.Metric = *update.Metric
438		}
439		if update.Trigger != nil {
440			updated.Trigger = *update.Trigger
441		}
442		if update.Recover != nil {
443			updated.Recover = *update.Recover
444		}
445		if update.Enabled != nil {
446			updated.Enabled = *update.Enabled
447		}
448		if updated.Recover >= updated.Trigger {
449			return Rule{}, nil, ErrInvalidRule
450		}
451	
452		// End the active alert of the old version before publishing the new one.
453		var ended []*Alert
454		if rs.activeAlertID != 0 {
455			alert := cloneAlert(*state.alerts[rs.activeAlertID-1])
456			alert.Status = alertStatusEnded
457			alert.EndReason = endReasonRuleChanged
458			now := s.now().UTC()
459			alert.EndedAt = &now
460			ended = append(ended, &alert)
461			rs.activeAlertID = 0
462		}
463	
464		updated.Version++
465		updated.UpdatedAt = s.now().UTC()
466	
467		if s.wal != nil {
468			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: updated, Ended: ended}); err != nil {
469				return Rule{}, nil, storageUnavailable(err)
470			}
471		}
472		rs.rule = updated
473		for _, alert := range ended {
474			state.alerts[alert.ID-1] = alert
475		}
476		return cloneRule(updated), cloneAlerts(ended), nil
477	}
478	
479	// GetRule returns one rule.
480	func (s *Store) GetRule(id, ruleID string) (Rule, error) {
481		s.mu.RLock()
482		defer s.mu.RUnlock()
483		state, ok := s.devices[id]
484		if !ok {
485			return Rule{}, ErrDeviceNotFound
486		}
487		rs, ok := state.rules[ruleID]
488		if !ok {
489			return Rule{}, ErrRuleNotFound
490		}
491		return cloneRule(rs.rule), nil
492	}
493	
494	// ListRules returns a device's rules, ordered by rule id.
495	func (s *Store) ListRules(id string) ([]Rule, error) {
496		s.mu.RLock()
497		defer s.mu.RUnlock()
498		state, ok := s.devices[id]
499		if !ok {
500			return nil, ErrDeviceNotFound
501		}
502		rules := make([]Rule, 0, len(state.rules))
503		for _, rs := range state.rules {
504			rules = append(rules, cloneRule(rs.rule))
505		}
506		sort.Slice(rules, func(i, j int) bool { return rules[i].ID < rules[j].ID })
507		return rules, nil
508	}
509	
510	// AckAlert records the server time of the first acknowledgment. Repeated
511	// acknowledgments keep the original time and write nothing. It returns
512	// ErrDeviceNotFound for an unknown device and ErrAlertNotFound for an unknown
513	// alert id.
514	func (s *Store) AckAlert(id string, alertID int64) (Alert, error) {
515		s.mu.Lock()
516		defer s.mu.Unlock()
517		state, ok := s.devices[id]
518		if !ok {
519			return Alert{}, ErrDeviceNotFound
520		}
521		if alertID < 1 || int(alertID) > len(state.alerts) {
522			return Alert{}, ErrAlertNotFound
523		}
524		alert := state.alerts[alertID-1]
525		if alert.AcknowledgedAt != nil {
526			return cloneAlert(*alert), nil
527		}
528		now := s.now().UTC()
529		if s.wal != nil {
530			if err := s.wal.appendRecord(recAlertAck, walAlertAck{
531				DeviceID: id, AlertID: alertID, AcknowledgedAt: now,
532			}); err != nil {
533				return Alert{}, storageUnavailable(err)
534			}
535		}
536		alert.AcknowledgedAt = &now
537		return cloneAlert(*alert), nil
538	}
539	
540	// ListAlerts returns a device's alerts with the given filters, ordered by
541	// alert id.
542	func (s *Store) ListAlerts(id string, filter AlertFilter) ([]Alert, error) {
543		s.mu.RLock()
544		defer s.mu.RUnlock()
545		state, ok := s.devices[id]
546		if !ok {
547			return nil, ErrDeviceNotFound
548		}
549		if filter.RuleID != "" {
550			if _, ok := state.rules[filter.RuleID]; !ok {
551				return nil, ErrRuleNotFound
552			}
553		}
554		alerts := make([]Alert, 0, len(state.alerts))
555		for _, alert := range state.alerts {
556			if filter.RuleID != "" && alert.RuleID != filter.RuleID {
557				continue
558			}
559			if filter.Status != "" && alert.Status != filter.Status {
560				continue
561			}
562			if filter.Acknowledged != nil {
563				acknowledged := alert.AcknowledgedAt != nil
564				if *filter.Acknowledged != acknowledged {
565					continue
566				}
567			}
568			alerts = append(alerts, cloneAlert(*alert))
569		}
570		return alerts, nil
571	}
572	
573	// alertEvaluator applies accepted samples to a device's enabled rules without
574	// mutating state until commit. It tracks which rule currently has an active
575	// alert so a trigger and a recovery inside the same batch are both handled in
576	// order.
577	type alertEvaluator struct {
578		state        *deviceState
579		activeByRule map[string]int64 // ruleID -> active alert id (0 when none)
580		created      []*Alert
581		ended        []*Alert
582		nextID       int64
583	}
584	
585	func newAlertEvaluator(state *deviceState) *alertEvaluator {
586		eval := &alertEvaluator{
587			state:        state,
588			activeByRule: make(map[string]int64, len(state.rules)),
589			nextID:       int64(len(state.alerts)) + 1,
590		}
591		for id, rs := range state.rules {
592			eval.activeByRule[id] = rs.activeAlertID
593		}
594		return eval
595	}
596	
597	// evaluate judges one accepted sample. A value at or above the trigger opens
598	// an alert (or keeps the existing one); a value at or below the recovery
599	// threshold ends the active alert; anything in between or a missing metric
600	// leaves state unchanged.
601	func (eval *alertEvaluator) evaluate(seq int64, observedAt time.Time, values map[string]float64) {
602		for _, rs := range eval.state.rules {
603			if !rs.rule.Enabled {
604				continue
605			}
606			value, ok := values[rs.rule.Metric]
607			if !ok {
608				continue
609			}
610			activeID := eval.activeByRule[rs.rule.ID]
611			if value >= rs.rule.Trigger && activeID == 0 {
612				alert := &Alert{
613					ID:                eval.nextID,
614					RuleID:            rs.rule.ID,
615					RuleVersion:       rs.rule.Version,
616					Metric:            rs.rule.Metric,
617					Trigger:           rs.rule.Trigger,
618					Recover:           rs.rule.Recover,
619					Status:            alertStatusActive,
620					TriggerSequence:   seq,
621					TriggerValue:      value,
622					TriggerObservedAt: observedAt,
623				}
624				eval.nextID++
625				eval.created = append(eval.created, alert)
626				eval.activeByRule[rs.rule.ID] = alert.ID
627			} else if value <= rs.rule.Recover && activeID != 0 {
628				var source *Alert
629				if activeID <= int64(len(eval.state.alerts)) {
630					source = eval.state.alerts[activeID-1]
631				} else {
632					source = eval.created[activeID-int64(len(eval.state.alerts))-1]
633				}
634				alert := cloneAlert(*source)
635				alert.Status = alertStatusEnded
636				alert.EndReason = endReasonRecovered
637				alert.RecoverSequence = &seq
638				alert.RecoverValue = &value
639				alert.RecoverObservedAt = &observedAt
640				eval.ended = append(eval.ended, &alert)
641				eval.activeByRule[rs.rule.ID] = 0
642			}
643		}
644	}
645	
646	// commit publishes the planned alert changes to the device state.
647	func (eval *alertEvaluator) commit() {
648		applyAlertChanges(eval.state, eval.created, eval.ended)
649	}
650	
651	// applyAlertChanges appends created alerts and replaces ended ones, keeping
652	// each rule's active-alert pointer in sync. It is shared by live evaluation
653	// and WAL recovery.
654	func applyAlertChanges(state *deviceState, created, ended []*Alert) {
655		for _, alert := range created {
656			state.alerts = append(state.alerts, alert)
657			if rs, ok := state.rules[alert.RuleID]; ok {
658				rs.activeAlertID = alert.ID
659			}
660		}
661		for _, alert := range ended {
662			state.alerts[alert.ID-1] = alert
663			if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
664				rs.activeAlertID = 0
665			}
666		}
667	}
668	
669	func cloneRule(rule Rule) Rule {
670		return rule
671	}
672	
673	func cloneAlert(alert Alert) Alert {
674		if alert.RecoverSequence != nil {
675			seq := *alert.RecoverSequence
676			alert.RecoverSequence = &seq
677		}
678		if alert.RecoverValue != nil {
679			value := *alert.RecoverValue
680			alert.RecoverValue = &value
681		}
682		if alert.RecoverObservedAt != nil {
683			t := *alert.RecoverObservedAt
684			alert.RecoverObservedAt = &t
685		}
686		if alert.EndedAt != nil {
687			t := *alert.EndedAt
688			alert.EndedAt = &t
689		}
690		if alert.AcknowledgedAt != nil {
691			t := *alert.AcknowledgedAt
692			alert.AcknowledgedAt = &t
693		}
694		return alert
695	}
696	
697	func cloneAlerts(alerts []*Alert) []*Alert {
698		if alerts == nil {
699			return nil
700		}
701		cloned := make([]*Alert, len(alerts))
702		for i, alert := range alerts {
703			c := cloneAlert(*alert)
704			cloned[i] = &c
705		}
706		return cloned
707	}
708	
709	// History returns one page of a device's event history. afterIndex is the first
710	// 0-based event slot to scan (0 for the first page); limit caps the number of
711	// matching events returned. bound pins the scan to sequences no larger than
712	// bound; a zero bound means "current maximum", which is then returned so
713	// callers can pin subsequent pages. nextIndex is the slot a following page
714	// should start at when hasMore is true. Concurrent writes therefore cannot
715	// skip or duplicate rows within a paged walk.
716	func (s *Store) History(id string, filter HistoryFilter, afterIndex, bound int64, limit int) (events []Event, appliedBound, nextIndex int64, hasMore bool, err error) {
717		s.mu.RLock()
718		defer s.mu.RUnlock()
719		state, ok := s.devices[id]
720		if !ok {
721			return nil, 0, 0, false, ErrDeviceNotFound
722		}
723		highWater := int64(len(state.events))
724		if bound == 0 {
725			bound = highWater
726		}
727		events = make([]Event, 0, limit)
728		for index := afterIndex; index < bound; index++ {
729			event := state.events[index]
730			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
731				continue
732			}
733			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
734				continue
735			}
736			if len(events) < limit {
737				events = append(events, cloneEvent(event))
738				continue
739			}
740			// This match belongs to the next page; resume scanning here so rows in
741			// the gap are never examined twice.
742			return events, bound, index, true, nil
743		}
744		return events, bound, bound, false, nil
745	}
746	
747	func (s *Store) Snapshot() []Device {
748		s.mu.RLock()
749		defer s.mu.RUnlock()
750		result := make([]Device, 0, len(s.devices))
751		for _, state := range s.devices {
752			result = append(result, cloneDevice(state.device))
753		}
754		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
755		return result
756	}
757	
758	func cloneDevice(device Device) Device {
759		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
760		return device
761	}
762	
763	func cloneEvent(event Event) Event {
764		event.Values = cloneTelemetry(event.Values)
765		return event
766	}
767	
768	func cloneTelemetry(values map[string]float64) map[string]float64 {
769		if values == nil {
770			return nil
771		}
772		cloned := make(map[string]float64, len(values))
773		for key, value := range values {
774			cloned[key] = value
775		}
776		return cloned
777	}
778	
779	// sameInstant compares times as UTC instants.
780	func sameInstant(a, b time.Time) bool {
781		return a.UTC().Equal(b.UTC())
782	}
783	
784	// sameValues compares metric maps by key and value.
785	func sameValues(a, b map[string]float64) bool {
786		if len(a) != len(b) {
787			return false
788		}
789		for key, value := range a {
790			other, ok := b[key]
791			if !ok || value != other {
792				return false
793			}
794		}
795		return true
796	}
797	
798	// sameOrderedSamples reports whether two batches carry the same samples in the
799	// same order, compared as UTC instants and key/value maps.
800	func sameOrderedSamples(a, b []Sample) bool {
801		if len(a) != len(b) {
802			return false
803		}
804		for i := range a {
805			if a[i].EventID != b[i].EventID ||
806				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
807				!sameValues(a[i].Values, b[i].Values) {
808				return false
809			}
810		}
811		return true
812	}
813

