68	func (h *handler) telemetry(w http.ResponseWriter, r *http.Request) {
69		values := map[string]float64{}
70		if err := decodeJSON(r, &values); err != nil || len(values) == 0 {
71			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "telemetry values are required"})
72			return
