267			ID      string  `json:"id"`
268			Metric  string  `json:"metric"`
269			Trigger float64 `json:"trigger"`
270			Recover float64 `json:"recover"`
271		}
272		if err := decodeJSON(r, &request); err != nil {
273			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
274			return
