344	func (h *handler) updateRule(w http.ResponseWriter, r *http.Request) {
345		var request struct {
346			Metric  *string  `json:"metric"`
347			Trigger *float64 `json:"trigger"`
348			Recover *float64 `json:"recover"`
349			Enabled *bool    `json:"enabled"`
350			Version int64    `json:"version"`
351		}
352		if err := decodeJSON(r, &request); err != nil {
353			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
354			return
355		}
356		if request.Version < 1 {
357			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version is required"})
358			return
359		}
360		if request.Metric != nil && strings.TrimSpace(*request.Metric) == "" {
361			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric must not be blank"})
362			return
363		}
364		if request.Trigger != nil && !finiteFloat(*request.Trigger) {
365			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "trigger must be a finite number"})
366			return
367		}
368		if request.Recover != nil && !finiteFloat(*request.Recover) {
369			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover must be a finite number"})
370			return
371		}
372		update := ruleUpdate{}
373		if request.Metric != nil {
374			metric := strings.TrimSpace(*request.Metric)
375			update.Metric = &metric
376		}
377		if request.Trigger != nil {
378			update.Trigger = request.Trigger
379		}
380		if request.Recover != nil {
381			update.Recover = request.Recover
382		}
383		if request.Enabled != nil {
384			update.Enabled = request.Enabled
385		}
386		rule, _, err := h.store.UpdateRule(r.PathValue("id"), r.PathValue("ruleId"), update, request.Version)
387		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrRuleNotFound) {
388			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
389			return
390		}
391		if errors.Is(err, ErrVersionConflict) {
392			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
393			return
394		}
395		if errors.Is(err, ErrInvalidRule) {
396			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
397			return
398		}
399		if errors.Is(err, ErrStorageUnavailable) {
400			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
401			return
402		}
403		if err != nil {
404			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
405			return
406		}
407		writeJSON(w, http.StatusOK, rule)
408	}
409	
410	// --- alerts -----------------------------------------------------------------
411	
412	func (h *handler) listAlerts(w http.ResponseWriter, r *http.Request) {
413		query := r.URL.Query()
414		filter := AlertFilter{RuleID: strings.TrimSpace(query.Get("ruleId"))}
415		if raw := strings.TrimSpace(query.Get("status")); raw != "" {
416			if raw != alertStatusActive && raw != alertStatusEnded {
417				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be active or ended"})
418				return
419			}
420			filter.Status = raw
421		}
422		if raw := strings.TrimSpace(query.Get("acknowledged")); raw != "" {
423			switch raw {
424			case "true", "1":
425				v := true
426				filter.Acknowledged = &v
427			case "false", "0":
428				v := false
429				filter.Acknowledged = &v
430			default:
431				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "acknowledged must be true or false"})
432				return
433			}
434		}
435		alerts, err := h.store.ListAlerts(r.PathValue("id"), filter)
436		if errors.Is(err, ErrDeviceNotFound) {
437			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
438			return
439		}
440		if errors.Is(err, ErrRuleNotFound) {
441			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
442			return
443		}
444		if err != nil {
445			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
446			return
447		}
448		writeJSON(w, http.StatusOK, map[string]any{"alerts": alerts})
449	}
450	
451	func (h *handler) ackAlert(w http.ResponseWriter, r *http.Request) {
452		alertID, err := strconv.ParseInt(r.PathValue("alertId"), 10, 64)
453		if err != nil || alertID < 1 {
454			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "alertId must be a positive integer"})
455			return
456		}
457		alert, err := h.store.AckAlert(r.PathValue("id"), alertID)
458		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrAlertNotFound) {
459			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
460			return
461		}
462		if errors.Is(err, ErrStorageUnavailable) {
463			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
464			return
465		}
466		if err != nil {
467			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
468			return
469		}
470		writeJSON(w, http.StatusOK, alert)
471	}
472	
473	func finiteFloat(value float64) bool {
474		return !math.IsNaN(value) && !math.IsInf(value, 0)
475	}
476	
477	func hasBlankKey(values map[string]float64) bool {
478		for key := range values {
479			if strings.TrimSpace(key) == "" {
480				return true
481			}
482		}
483		return false
484	}
485	
486	func finiteValues(values map[string]float64) bool {
487		for _, value := range values {
488			if math.IsNaN(value) || math.IsInf(value, 0) {
489				return false
490			}
491		}
492		return true
493	}
494	
495	func decodeJSON(r *http.Request, target any) error {
496		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
497		decoder.DisallowUnknownFields()
498		return decoder.Decode(target)
499	}
500	
501	// decodeSingleJSON requires the body to be exactly one JSON value, rejecting
502	// trailing data such as a second JSON object or concatenated documents.
503	func decodeSingleJSON(r *http.Request, target any) error {
504		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
505		decoder.DisallowUnknownFields()
506		if err := decoder.Decode(target); err != nil {
507			return err
508		}
509		var trailing any
510		if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
511			return errors.New("body must contain a single JSON value")
512		}
513		return nil
514	}
515	
516	func writeJSON(w http.ResponseWriter, status int, value any) {
517		w.Header().Set("Content-Type", "application/json")
518		w.WriteHeader(status)
519		_ = json.NewEncoder(w).Encode(value)
520	}
