1	package fleet
2	
3	import (
4		"crypto/rand"
5		"encoding/binary"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"hash/crc32"
10		"io"
11		"io/fs"
12		"os"
13		"path/filepath"
14		"strings"
15		"sync"
16		"syscall"
17		"time"
18	)
19	
20	// Persistent mode stores every acknowledged mutation as one checksummed record
21	// in an append-only write-ahead log. A record is the commit unit: either the
22	// whole record is durable (and visible after recovery) or none of it is, so a
23	// replay batch can never leave half of its samples behind.
24	//
25	// Commit protocol per write (WAL frame and commit journal are separate files so
26	// the commit decision never depends on parsing a possibly torn frame length):
27	//
28	//  1. write the frame at the committed offset and fsync the WAL;
29	//  2. append a fixed-size entry carrying the new committed WAL length to the
30	//     commit journal and fsync it;
31	//  3. only then report success.
32	//
33	// Recovery reads the committed length T from the journal, verifies that WAL
34	// bytes [header, T) form an exact chain of valid frames, applies them, and
35	// treats bytes (T, EOF] as the residue of an unacknowledged write. Damage to
36	// committed bytes always fails startup instead of being trimmed away.
37	
38	const (
39		walName     = "wal.log"
40		commitName  = "commit.log"
41		lockName    = "lock"
42		walMagic    = "EDGEFLET" // 8 bytes
43		headerLen   = 16         // magic(8) + version(4) + flags(4)
44		walVersion  = 1
45		commitEntry = 12 // [committed WAL length uint64 LE][crc32 LE]
46	
47		// maxRecordPayload bounds a single frame; HTTP bodies are capped at 1MiB so
48		// this only rejects absurd length fields from damaged files.
49		maxRecordPayload = 8 << 20
50	)
51	
52	const (
53		recInstance byte = 1 + iota
54		recRegister
55		recTelemetry
56		recReplay
57		recRule
58		recAlertAck
59		recConfigPublish
60		recConfigReceipt
61	)
62	
63	// ErrStorageUnavailable wraps a durable-write failure at runtime. A request
64	// that fails this way never mutated queryable state.
65	var ErrStorageUnavailable = errors.New("storage unavailable")
66	
67	var crcTable = crc32.MakeTable(crc32.Castagnoli)
68	
69	// walSink is the commit log behind a persistent store.
70	type walSink interface {
71		appendRecord(recType byte, value any) error
72	}
73	
74	type walInstance struct {
75		InstanceID []byte `json:"instanceId"`
76	}
77	
78	type walRegister struct {
79		ID           string    `json:"id"`
80		Site         string    `json:"site"`
81		RegisteredAt time.Time `json:"registeredAt"`
82		LastSeenAt   time.Time `json:"lastSeenAt"`
83	}
84	
85	type walTelemetry struct {
86		DeviceID   string             `json:"deviceId"`
87		Sequence   int64              `json:"sequence"`
88		ObservedAt time.Time          `json:"observedAt"`
89		Values     map[string]float64 `json:"values"`
90		// Alerts and Ended carry the alert changes judged from this sample, in the
91		// same commit unit as the sample itself. Absent in records written before
92		// alerting existed.
93		Alerts []*Alert `json:"alerts,omitempty"`
94		Ended  []*Alert `json:"ended,omitempty"`
95	}
96	
97	type walSample struct {
98		EventID    string             `json:"eventId"`
99		ObservedAt time.Time          `json:"observedAt"`
100		Values     map[string]float64 `json:"values"`
101	}
102	
103	// walReplay is one committed batch. Samples holds the full ordered batch
104	// (duplicates included) and Receipt the first-acceptance receipt; new events
105	// and their sequences are derived by zipping the two during recovery. Alerts
106	// and Ended carry the alert changes judged from the batch's new samples, in
107	// the same commit unit as the batch itself.
108	type walReplay struct {
109		DeviceID      string             `json:"deviceId"`
110		BatchID       string             `json:"batchId"`
111		Samples       []walSample        `json:"samples"`
112		Receipt       ReplayReceipt      `json:"receipt"`
113		LastSeenAt    *time.Time         `json:"lastSeenAt,omitempty"`
114		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
115		Alerts        []*Alert           `json:"alerts,omitempty"`
116		Ended         []*Alert           `json:"ended,omitempty"`
117	}
118	
119	// walRule is one committed rule create or update. Ended holds the alerts the
120	// update terminated with reason rule_changed, in the same commit unit.
121	type walRule struct {
122		DeviceID string   `json:"deviceId"`
123		Rule     Rule     `json:"rule"`
124		Ended    []*Alert `json:"ended,omitempty"`
125	}
126	
127	// walAlertAck is one committed alert acknowledgment.
128	type walAlertAck struct {
129		DeviceID       string    `json:"deviceId"`
130		AlertID        int64     `json:"alertId"`
131		AcknowledgedAt time.Time `json:"acknowledgedAt"`
132	}
133	
134	// walConfigPublish is one committed configuration version together with the
135	// requestId dedup record of its first publish.
136	type walConfigPublish struct {
137		DeviceID    string          `json:"deviceId"`
138		RequestID   string          `json:"requestId"`
139		BaseVersion int64           `json:"baseVersion"`
140		Version     int64           `json:"version"`
141		Content     json.RawMessage `json:"content"`
142		PublishedAt time.Time       `json:"publishedAt"`
143	}
144	
145	// walConfigReceipt is one committed device application receipt.
146	type walConfigReceipt struct {
147		DeviceID   string    `json:"deviceId"`
148		ReceiptID  string    `json:"receiptId"`
149		Version    int64     `json:"version"`
150		Success    bool      `json:"success"`
151		Reason     string    `json:"reason,omitempty"`
152		ReceivedAt time.Time `json:"receivedAt"`
153	}
154	
155	// walFile is the durable backend. walDurable is the committed WAL length (also
156	// the next frame offset); commitDurable is the journal length. Both files are
157	// truncated back to those offsets before every write, so residue left by a
158	// failed write can never be mistaken for later committed data.
159	type walFile struct {
160		walF          *os.File
161		commitF       *os.File
162		lock          *os.File
163		mu            sync.Mutex
164		walDurable    int64
165		commitDurable int64
166	}
167	
168	func (w *walFile) appendRecord(recType byte, value any) error {
169		frame, err := marshalFrame(recType, value)
170		if err != nil {
171			return err
172		}
173		w.mu.Lock()
174		defer w.mu.Unlock()
175	
176		// Remove residue any previous failed attempt may have left, then phase 1.
177		if err := w.walF.Truncate(w.walDurable); err != nil {
178			return err
179		}
180		if err := pwriteAll(w.walF, frame, w.walDurable); err != nil {
181			return err
182		}
183		if err := w.walF.Sync(); err != nil {
184			return err
185		}
186	
187		// Phase 2: publish the new committed length in the fixed-width journal.
188		newLength := w.walDurable + int64(len(frame))
189		entry := make([]byte, commitEntry)
190		binary.LittleEndian.PutUint64(entry[0:8], uint64(newLength))
191		binary.LittleEndian.PutUint32(entry[8:12], commitCRC(entry[0:8]))
192		if err := w.commitF.Truncate(w.commitDurable); err != nil {
193			return err
194		}
195		if err := pwriteAll(w.commitF, entry, w.commitDurable); err != nil {
196			return err
197		}
198		if err := w.commitF.Sync(); err != nil {
199			return err
200		}
201	
202		w.walDurable = newLength
203		w.commitDurable += int64(commitEntry)
204		return nil
205	}
206	
207	func commitCRC(sizeBytes []byte) uint32 {
208		return crc32.Checksum(sizeBytes, crcTable)
209	}
210	
211	func pwriteAll(f *os.File, buf []byte, offset int64) error {
212		for len(buf) > 0 {
213			n, err := f.WriteAt(buf, offset)
214			if err != nil {
215				return err
216			}
217			buf = buf[n:]
218			offset += int64(n)
219		}
220		return nil
221	}
222	
223	func (w *walFile) Close() error {
224		walErr := w.walF.Close()
225		commitErr := w.commitF.Close()
226		// Closing the lock fd releases the flock; a killed process releases it via
227		// the kernel, so no manual lock cleanup is ever required.
228		lockErr := w.lock.Close()
229		if walErr != nil {
230			return walErr
231		}
232		if commitErr != nil {
233			return commitErr
234		}
235		return lockErr
236	}
237	
238	// NewPersistentStore opens (or creates) a data directory and finishes full
239	// recovery before returning. It fails rather than falling back to memory when
240	// the directory cannot be created, locked, read or written, when another
241	// process already holds the directory, or when committed data is corrupt or
242	// in an unsupported format.
243	func NewPersistentStore(dir string) (_ *Store, err error) {
244		if fi, statErr := os.Stat(dir); statErr == nil {
245			if !fi.IsDir() {
246				return nil, fmt.Errorf("data path %s is not a directory", dir)
247			}
248		} else if !errors.Is(statErr, fs.ErrNotExist) {
249			return nil, fmt.Errorf("cannot access data directory %s: %w", dir, statErr)
250		}
251		if err := os.MkdirAll(dir, 0o755); err != nil {
252			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
253		}
254	
255		// Take the inter-process lock before reading or writing any business data.
256		lockPath := filepath.Join(dir, lockName)
257		lockFile, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
258		if err != nil {
259			return nil, fmt.Errorf("cannot open lock file %s: %w", lockPath, err)
260		}
261		if lockErr := syscall.Flock(int(lockFile.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); lockErr != nil {
262			_ = lockFile.Close()
263			return nil, fmt.Errorf("data directory %s is already in use by another edge-fleet process: %w", dir, lockErr)
264		}
265		handedOff := false
266		defer func() {
267			if !handedOff {
268				_ = lockFile.Close()
269			}
270		}()
271	
272		walPath := filepath.Join(dir, walName)
273		commitPath := filepath.Join(dir, commitName)
274		walF, err := os.OpenFile(walPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
275		if err != nil {
276			return nil, fmt.Errorf("cannot open write-ahead log %s: %w", walPath, err)
277		}
278		commitF, err := os.OpenFile(commitPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
279		if err != nil {
280			_ = walF.Close()
281			return nil, fmt.Errorf("cannot open commit journal %s: %w", commitPath, err)
282		}
283		committed := false
284		defer func() {
285			if !committed {
286				_ = walF.Close()
287				_ = commitF.Close()
288			}
289		}()
290	
291		walInfo, err := walF.Stat()
292		if err != nil {
293			return nil, fmt.Errorf("cannot stat write-ahead log %s: %w", walPath, err)
294		}
295		if walInfo.Size() == 0 {
296			if _, err := walF.WriteAt(walHeader(), 0); err != nil {
297				return nil, fmt.Errorf("cannot initialise write-ahead log %s: %w", walPath, err)
298			}
299			if err := walF.Sync(); err != nil {
300				return nil, fmt.Errorf("cannot flush write-ahead log %s: %w", walPath, err)
301			}
302		}
303	
304		walData, err := io.ReadAll(walF)
305		if err != nil {
306			return nil, fmt.Errorf("cannot read write-ahead log %s: %w", walPath, err)
307		}
308		commitData, err := io.ReadAll(commitF)
309		if err != nil {
310			return nil, fmt.Errorf("cannot read commit journal %s: %w", commitPath, err)
311		}
312		if len(walData) < headerLen || string(walData[0:8]) != walMagic {
313			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad magic header", walPath)
314		}
315		version := binary.LittleEndian.Uint32(walData[8:12])
316		if version != walVersion {
317			return nil, fmt.Errorf("write-ahead log %s uses unsupported format version %d (this server supports %d)", walPath, version, walVersion)
318		}
319		if binary.LittleEndian.Uint32(walData[12:16]) != 0 {
320			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad header flags", walPath)
321		}
322	
323		// Recover the committed WAL length from the fixed-width journal. A short
324		// final block is a torn append from a write that never reported success;
325		// a full block with a bad CRC is committed-data damage. Entries must chain
326		// strictly forward and never point past the WAL. For a fresh journal the
327		// committed prefix is the header itself.
328		walDurable, commitDurable := int64(headerLen), int64(0)
329		for pos := 0; pos < len(commitData); pos += commitEntry {
330			if len(commitData)-pos < commitEntry {
331				break // torn tail: discarded by the truncate below
332			}
333			block := commitData[pos : pos+commitEntry]
334			declared := int64(binary.LittleEndian.Uint64(block[0:8]))
335			if binary.LittleEndian.Uint32(block[8:12]) != commitCRC(block[0:8]) {
336				return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: bad checksum (files left untouched)", commitPath, pos)
337			}
338			if declared <= walDurable || declared > int64(len(walData)) || declared < headerLen {
339				return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: committed length %d is inconsistent", commitPath, pos, declared)
340			}
341			walDurable = declared
342			commitDurable = int64(pos + commitEntry)
343		}
344	
345		// Every byte the journal claims committed must form an exact chain of
346		// valid, in-range frames. Failure here is damage to acknowledged data.
347		type parsedFrame struct {
348			recType byte
349			payload []byte
350		}
351		frames := make([]parsedFrame, 0)
352		pos := headerLen
353		for int64(pos) < walDurable {
354			if pos+5 > len(walData) {
355				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: truncated frame inside committed prefix", walPath, pos)
356			}
357			length := int(binary.LittleEndian.Uint32(walData[pos : pos+4]))
358			frameLen := 5 + length + 4
359			if length > maxRecordPayload || int64(pos+frameLen) > walDurable {
360				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame length %d is invalid within the committed prefix", walPath, pos, length)
361			}
362			recType := walData[pos+4]
363			payload := walData[pos+5 : pos+5+length]
364			wantCRC := binary.LittleEndian.Uint32(walData[pos+5+length : pos+frameLen])
365			if crc32.Checksum(walData[pos:pos+5+length], crcTable) != wantCRC {
366				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame failed its integrity check (file left untouched)", walPath, pos)
367			}
368			if recType < recInstance || recType > recConfigReceipt {
369				return nil, fmt.Errorf("write-ahead log %s uses unsupported record type %d at byte %d", walPath, recType, pos)
370			}
371			frames = append(frames, parsedFrame{recType: recType, payload: payload})
372			pos += frameLen
373		}
374		if int64(pos) != walDurable {
375			return nil, fmt.Errorf("write-ahead log %s is corrupt: committed length %d is not a frame boundary", walPath, walDurable)
376		}
377	
378		// Rebuild relational state from the committed frames, in order.
379		store := NewStore()
380		var instanceID []byte
381		sawInstance := false
382		for i, frame := range frames {
383			switch frame.recType {
384			case recInstance:
385				if sawInstance || i != 0 {
386					return nil, fmt.Errorf("write-ahead log %s is corrupt: instance marker out of place", walPath)
387				}
388				var rec walInstance
389				if err := json.Unmarshal(frame.payload, &rec); err != nil || len(rec.InstanceID) == 0 || len(rec.InstanceID) > 64 {
390					return nil, fmt.Errorf("write-ahead log %s is corrupt: invalid instance marker: %w", walPath, err)
391				}
392				instanceID = rec.InstanceID
393				sawInstance = true
394			case recRegister, recTelemetry, recReplay, recRule, recAlertAck, recConfigPublish, recConfigReceipt:
395				if !sawInstance {
396					return nil, fmt.Errorf("write-ahead log %s is corrupt: data record precedes instance marker", walPath)
397				}
398				if err := applyRecord(store, frame.recType, frame.payload); err != nil {
399					return nil, fmt.Errorf("write-ahead log %s is corrupt: %w", walPath, err)
400				}
401			}
402		}
403	
404		// Discard unacknowledged residue: bytes from a request that never reached
405		// its journal entry (crash mid-write or a request that returned 503).
406		if int64(len(walData)) != walDurable {
407			if err := walF.Truncate(walDurable); err != nil {
408				return nil, fmt.Errorf("cannot discard unacknowledged tail of %s: %w", walPath, err)
409			}
410			if err := walF.Sync(); err != nil {
411				return nil, fmt.Errorf("cannot flush truncated %s: %w", walPath, err)
412			}
413		}
414		if int64(len(commitData)) != commitDurable {
415			if err := commitF.Truncate(commitDurable); err != nil {
416				return nil, fmt.Errorf("cannot discard torn entry of %s: %w", commitPath, err)
417			}
418			if err := commitF.Sync(); err != nil {
419				return nil, fmt.Errorf("cannot flush truncated %s: %w", commitPath, err)
420			}
421		}
422	
423		wal := &walFile{
424			walF:          walF,
425			commitF:       commitF,
426			lock:          lockFile,
427			walDurable:    walDurable,
428			commitDurable: commitDurable,
429		}
430		if !sawInstance {
431			instanceID = newInstanceID()
432			if err := wal.appendRecord(recInstance, walInstance{InstanceID: instanceID}); err != nil {
433				return nil, fmt.Errorf("cannot write instance marker to %s: %w", walPath, err)
434			}
435		}
436		// Make freshly created directory entries durable as well.
437		if dirFile, err := os.Open(dir); err != nil {
438			return nil, fmt.Errorf("cannot open data directory %s for sync: %w", dir, err)
439		} else {
440			syncErr := syscall.Fsync(int(dirFile.Fd()))
441			_ = dirFile.Close()
442			if syncErr != nil {
443				return nil, fmt.Errorf("cannot flush data directory %s: %w", dir, syncErr)
444			}
445		}
446	
447		store.wal = wal
448		store.iid = instanceID
449		committed = true
450		handedOff = true
451		return store, nil
452	}
453	
454	// Close releases the WAL files and the directory lock.
455	func (s *Store) Close() error {
456		if closer, ok := s.wal.(interface{ Close() error }); ok {
457			return closer.Close()
458		}
459		return nil
460	}
461	
462	func storageUnavailable(err error) error {
463		return fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
464	}
465	
466	func walHeader() []byte {
467		header := make([]byte, headerLen)
468		copy(header[0:8], walMagic)
469		binary.LittleEndian.PutUint32(header[8:12], walVersion)
470		return header
471	}
472	
473	// marshalFrame frames one record as
474	// [length uint32 LE][type byte][payload][crc32 LE].
475	// The CRC covers length, type and payload, so even a damaged length field of
476	// the final frame fails verification instead of masquerading as a torn tail.
477	func marshalFrame(recType byte, value any) ([]byte, error) {
478		payload, err := json.Marshal(value)
479		if err != nil {
480			return nil, err
481		}
482		if len(payload) > maxRecordPayload {
483			return nil, fmt.Errorf("wal record too large: %d bytes", len(payload))
484		}
485		frame := make([]byte, 5+len(payload)+4)
486		binary.LittleEndian.PutUint32(frame[0:4], uint32(len(payload)))
487		frame[4] = recType
488		copy(frame[5:], payload)
489		binary.LittleEndian.PutUint32(frame[5+len(payload):], crc32.Checksum(frame[:5+len(payload)], crcTable))
490		return frame, nil
491	}
492	
493	// applyAlertRecord validates and applies the alert changes carried by a
494	// telemetry or replay record. It rejects relational inconsistency so a damaged
495	// WAL fails startup rather than producing broken alert state.
496	func applyAlertRecord(state *deviceState, created, ended []*Alert) error {
497		wantID := int64(len(state.alerts)) + 1
498		for _, alert := range created {
499			if alert == nil {
500				return errors.New("alert record contains a null create")
501			}
502			if alert.ID != wantID {
503				return fmt.Errorf("alert create id mismatch: got %d, want %d", alert.ID, wantID)
504			}
505			if alert.Status != alertStatusActive || alert.RuleID == "" || alert.Metric == "" ||
506				alert.TriggerSequence <= 0 || alert.TriggerObservedAt.IsZero() {
507				return fmt.Errorf("alert %d create is incomplete", alert.ID)
508			}
509			wantID++
510		}
511		maxID := int64(len(state.alerts) + len(created))
512		for _, alert := range ended {
513			if alert == nil {
514				return errors.New("alert record contains a null end")
515			}
516			if alert.ID < 1 || alert.ID > maxID {
517				return fmt.Errorf("alert end id %d out of range (1..%d)", alert.ID, maxID)
518			}
519			if alert.Status != alertStatusEnded || alert.EndReason != endReasonRecovered {
520				return fmt.Errorf("alert %d end is malformed", alert.ID)
521			}
522		}
523		applyAlertChanges(state, created, ended)
524		return nil
525	}
526	
527	// applyRecord rebuilds in-memory state from one committed record, rejecting
528	// any structural or relational inconsistency. It never calls the clock, so
529	// recovery cannot refresh device timestamps.
530	func applyRecord(s *Store, recType byte, payload []byte) error {
531		switch recType {
532		case recRegister:
533			var rec walRegister
534			if err := json.Unmarshal(payload, &rec); err != nil {
535				return fmt.Errorf("invalid register record: %w", err)
536			}
537			if rec.ID == "" || rec.RegisteredAt.IsZero() || rec.LastSeenAt.IsZero() {
538				return errors.New("register record missing fields")
539			}
540			if _, exists := s.devices[rec.ID]; exists {
541				return fmt.Errorf("duplicate registration for device %q", rec.ID)
542			}
543			s.devices[rec.ID] = &deviceState{
544				device: Device{
545					ID:           rec.ID,
546					Site:         rec.Site,
547					RegisteredAt: rec.RegisteredAt.UTC(),
548					LastSeenAt:   rec.LastSeenAt.UTC(),
549				},
550				byEvent: make(map[string]int64),
551				batches: make(map[string]storedBatch),
552				rules:   make(map[string]*ruleState),
553			}
554			return nil
555	
556		case recTelemetry:
557			var rec walTelemetry
558			if err := json.Unmarshal(payload, &rec); err != nil {
559				return fmt.Errorf("invalid telemetry record: %w", err)
560			}
561			state, ok := s.devices[rec.DeviceID]
562			if !ok {
563				return fmt.Errorf("telemetry for unknown device %q", rec.DeviceID)
564			}
565			if rec.Sequence != int64(len(state.events))+1 {
566				return fmt.Errorf("device %q telemetry sequence gap: got %d, want %d", rec.DeviceID, rec.Sequence, len(state.events)+1)
567			}
568			if rec.ObservedAt.IsZero() || len(rec.Values) == 0 {
569				return fmt.Errorf("device %q telemetry record missing fields", rec.DeviceID)
570			}
571			state.events = append(state.events, Event{
572				Sequence:   rec.Sequence,
573				ObservedAt: rec.ObservedAt.UTC(),
574				Values:     cloneTelemetry(rec.Values),
575			})
576			state.device.LastSeenAt = rec.ObservedAt.UTC()
577			state.device.LastTelemetry = cloneTelemetry(rec.Values)
578			if err := applyAlertRecord(state, rec.Alerts, rec.Ended); err != nil {
579				return err
580			}
581			return nil
582	
583		case recReplay:
584			var rec walReplay
585			if err := json.Unmarshal(payload, &rec); err != nil {
586				return fmt.Errorf("invalid replay record: %w", err)
587			}
588			state, ok := s.devices[rec.DeviceID]
589			if !ok {
590				return fmt.Errorf("replay for unknown device %q", rec.DeviceID)
591			}
592			if rec.BatchID == "" || len(rec.Samples) == 0 || len(rec.Samples) != len(rec.Receipt.SampleStatus) {
593				return fmt.Errorf("device %q replay record is incomplete", rec.DeviceID)
594			}
595			if rec.Receipt.BatchID != rec.BatchID {
596				return fmt.Errorf("device %q receipt batchId %q does not match %q", rec.DeviceID, rec.Receipt.BatchID, rec.BatchID)
597			}
598			if _, exists := state.batches[rec.BatchID]; exists {
599				return fmt.Errorf("device %q duplicate stored receipt for batch %q", rec.DeviceID, rec.BatchID)
600			}
601	
602			samples := make([]Sample, len(rec.Samples))
603			newCount, dupCount := 0, 0
604			lastNew := -1
605			for i, entry := range rec.Samples {
606				status := rec.Receipt.SampleStatus[i]
607				if entry.EventID == "" || entry.ObservedAt.IsZero() || len(entry.Values) == 0 {
608					return fmt.Errorf("device %q batch %q sample %d is incomplete", rec.DeviceID, rec.BatchID, i)
609				}
610				if status.EventID != entry.EventID {
611					return fmt.Errorf("device %q batch %q receipt/sample eventId mismatch at %d", rec.DeviceID, rec.BatchID, i)
612				}
613				samples[i] = Sample{
614					EventID:    entry.EventID,
615					ObservedAt: entry.ObservedAt.UTC(),
616					Values:     cloneTelemetry(entry.Values),
617				}
618				if sequence, seen := state.byEvent[entry.EventID]; seen {
619					existing := state.events[sequence-1]
620					if !sameInstant(existing.ObservedAt, entry.ObservedAt) || !sameValues(existing.Values, entry.Values) {
621						return fmt.Errorf("device %q dedupe record for %q disagrees with history", rec.DeviceID, entry.EventID)
622					}
623					if !status.Duplicate || status.Sequence != sequence {
624						return fmt.Errorf("device %q receipt for %q should reuse sequence %d", rec.DeviceID, entry.EventID, sequence)
625					}
626					dupCount++
627					continue
628				}
629				if status.Duplicate {
630					return fmt.Errorf("device %q receipt marks unseen event %q as duplicate", rec.DeviceID, entry.EventID)
631				}
632				want := int64(len(state.events)) + 1
633				if status.Sequence != want {
634					return fmt.Errorf("device %q batch %q sequence mismatch for %q: got %d, want %d", rec.DeviceID, rec.BatchID, entry.EventID, status.Sequence, want)
635				}
636				state.events = append(state.events, Event{
637					Sequence:   status.Sequence,
638					ObservedAt: entry.ObservedAt.UTC(),
639					Values:     cloneTelemetry(entry.Values),
640				})
641				state.byEvent[entry.EventID] = status.Sequence
642				newCount++
643				lastNew = i
644			}
645			if rec.Receipt.NewCount != newCount || rec.Receipt.Duplicate != dupCount {
646				return fmt.Errorf("device %q batch %q receipt counts disagree with samples (%d/%d vs %d/%d)",
647					rec.DeviceID, rec.BatchID, rec.Receipt.NewCount, rec.Receipt.Duplicate, newCount, dupCount)
648			}
649	
650			if newCount > 0 {
651				if rec.LastSeenAt == nil || rec.LastSeenAt.IsZero() {
652					return fmt.Errorf("device %q batch %q missing recorded receive time", rec.DeviceID, rec.BatchID)
653				}
654				if !sameValues(rec.LastTelemetry, samples[lastNew].Values) {
655					return fmt.Errorf("device %q batch %q last telemetry disagrees with last new sample", rec.DeviceID, rec.BatchID)
656				}
657				state.device.LastSeenAt = rec.LastSeenAt.UTC()
658				state.device.LastTelemetry = cloneTelemetry(rec.LastTelemetry)
659			} else if rec.LastSeenAt != nil || len(rec.LastTelemetry) != 0 {
660				return fmt.Errorf("device %q all-duplicate batch %q unexpectedly refreshed device state", rec.DeviceID, rec.BatchID)
661			}
662	
663			state.batches[rec.BatchID] = storedBatch{samples: samples, receipt: cloneReceipt(rec.Receipt)}
664			if err := applyAlertRecord(state, rec.Alerts, rec.Ended); err != nil {
665				return err
666			}
667			return nil
668	
669		case recRule:
670			var rec walRule
671			if err := json.Unmarshal(payload, &rec); err != nil {
672				return fmt.Errorf("invalid rule record: %w", err)
673			}
674			state, ok := s.devices[rec.DeviceID]
675			if !ok {
676				return fmt.Errorf("rule for unknown device %q", rec.DeviceID)
677			}
678			if rec.Rule.ID == "" || rec.Rule.Metric == "" || rec.Rule.Version < 1 ||
679				rec.Rule.CreatedAt.IsZero() || rec.Rule.UpdatedAt.IsZero() {
680				return fmt.Errorf("device %q rule record is incomplete", rec.DeviceID)
681			}
682			if existing, exists := state.rules[rec.Rule.ID]; exists {
683				if existing.rule.Version != rec.Rule.Version-1 {
684					return fmt.Errorf("device %q rule %q version gap: got %d, want %d",
685						rec.DeviceID, rec.Rule.ID, rec.Rule.Version, existing.rule.Version+1)
686				}
687				existing.rule = rec.Rule
688			} else {
689				if rec.Rule.Version != 1 {
690					return fmt.Errorf("device %q rule %q first record has version %d, want 1",
691						rec.DeviceID, rec.Rule.ID, rec.Rule.Version)
692				}
693				state.rules[rec.Rule.ID] = &ruleState{rule: rec.Rule}
694			}
695			for _, alert := range rec.Ended {
696				if alert == nil || alert.ID < 1 || int(alert.ID) > len(state.alerts) {
697					return fmt.Errorf("device %q rule %q ends unknown alert", rec.DeviceID, rec.Rule.ID)
698				}
699				if alert.Status != alertStatusEnded || alert.EndReason != endReasonRuleChanged || alert.EndedAt == nil {
700					return fmt.Errorf("device %q rule %q end of alert %d is malformed", rec.DeviceID, rec.Rule.ID, alert.ID)
701				}
702				state.alerts[alert.ID-1] = alert
703				if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
704					rs.activeAlertID = 0
705				}
706			}
707			return nil
708	
709		case recAlertAck:
710			var rec walAlertAck
711			if err := json.Unmarshal(payload, &rec); err != nil {
712				return fmt.Errorf("invalid alert ack record: %w", err)
713			}
714			state, ok := s.devices[rec.DeviceID]
715			if !ok {
716				return fmt.Errorf("alert ack for unknown device %q", rec.DeviceID)
717			}
718			if rec.AlertID < 1 || int(rec.AlertID) > len(state.alerts) {
719				return fmt.Errorf("device %q ack for unknown alert %d", rec.DeviceID, rec.AlertID)
720			}
721			if rec.AcknowledgedAt.IsZero() {
722				return fmt.Errorf("device %q ack for alert %d missing time", rec.DeviceID, rec.AlertID)
723			}
724			alert := state.alerts[rec.AlertID-1]
725			if alert.AcknowledgedAt == nil {
726				t := rec.AcknowledgedAt.UTC()
727				alert.AcknowledgedAt = &t
728			}
729			return nil
730	
731		case recConfigPublish:
732			var rec walConfigPublish
733			if err := json.Unmarshal(payload, &rec); err != nil {
734				return fmt.Errorf("invalid config publish record: %w", err)
735			}
736			state, ok := s.devices[rec.DeviceID]
737			if !ok {
738				return fmt.Errorf("config publish for unknown device %q", rec.DeviceID)
739			}
740			if rec.RequestID == "" || rec.PublishedAt.IsZero() {
741				return fmt.Errorf("device %q config publish record is incomplete", rec.DeviceID)
742			}
743			if !isNonEmptyJSONObject(rec.Content) {
744				return fmt.Errorf("device %q config v%d content is not a non-empty JSON object", rec.DeviceID, rec.Version)
745			}
746			if state.config == nil {
747				state.config = newConfigState()
748			}
749			cfg := state.config
750			if rec.Version != int64(len(cfg.versions))+1 {
751				return fmt.Errorf("device %q config version gap: got %d, want %d",
752					rec.DeviceID, rec.Version, len(cfg.versions)+1)
753			}
754			if rec.BaseVersion != rec.Version-1 {
755				return fmt.Errorf("device %q config v%d base %d does not precede version",
756					rec.DeviceID, rec.Version, rec.BaseVersion)
757			}
758			if _, dup := cfg.publishes[rec.RequestID]; dup {
759				return fmt.Errorf("device %q duplicate config publish request %q", rec.DeviceID, rec.RequestID)
760			}
761			if rec.Version <= cfg.applied {
762				return fmt.Errorf("device %q config v%d published after applied %d", rec.DeviceID, rec.Version, cfg.applied)
763			}
764			content := cloneJSON(rec.Content)
765			cfg.versions = append(cfg.versions, publishedConfig{
766				content:     content,
767				publishedAt: rec.PublishedAt.UTC(),
768			})
769			cfg.publishes[rec.RequestID] = storedPublish{
770				baseVersion: rec.BaseVersion,
771				content:     cloneJSON(content),
772				result: ConfigPublishResult{
773					RequestID:   rec.RequestID,
774					Version:     rec.Version,
775					Content:     cloneJSON(content),
776					PublishedAt: rec.PublishedAt.UTC(),
777				},
778			}
779			return nil
780	
781		case recConfigReceipt:
782			var rec walConfigReceipt
783			if err := json.Unmarshal(payload, &rec); err != nil {
784				return fmt.Errorf("invalid config receipt record: %w", err)
785			}
786			state, ok := s.devices[rec.DeviceID]
787			if !ok {
788				return fmt.Errorf("config receipt for unknown device %q", rec.DeviceID)
789			}
790			if rec.ReceiptID == "" || rec.ReceivedAt.IsZero() {
791				return fmt.Errorf("device %q config receipt record is incomplete", rec.DeviceID)
792			}
793			if !rec.Success && strings.TrimSpace(rec.Reason) == "" {
794				return fmt.Errorf("device %q config receipt %q fails without a reason", rec.DeviceID, rec.ReceiptID)
795			}
796			if state.config == nil {
797				state.config = newConfigState()
798			}
799			cfg := state.config
800			if rec.Version < 1 || rec.Version > int64(len(cfg.versions)) {
801				return fmt.Errorf("device %q config receipt %q for unknown version %d", rec.DeviceID, rec.ReceiptID, rec.Version)
802			}
803			if _, dup := cfg.byReceipt[rec.ReceiptID]; dup {
804				return fmt.Errorf("device %q duplicate config receipt %q", rec.DeviceID, rec.ReceiptID)
805			}
806			if rec.Version < cfg.applied {
807				return fmt.Errorf("device %q config receipt %q version %d is below applied %d",
808					rec.DeviceID, rec.ReceiptID, rec.Version, cfg.applied)
809			}
810			if !rec.Success && rec.Version <= cfg.applied {
811				return fmt.Errorf("device %q config receipt %q fails an already applied version %d",
812					rec.DeviceID, rec.ReceiptID, rec.Version)
813			}
814			receipt := ConfigReceipt{
815				ReceiptID:  rec.ReceiptID,
816				Version:    rec.Version,
817				Success:    rec.Success,
818				Reason:     rec.Reason,
819				ReceivedAt: rec.ReceivedAt.UTC(),
820			}
821			cfg.receipts = append(cfg.receipts, receipt)
822			cfg.byReceipt[rec.ReceiptID] = receipt
823			if rec.Success && rec.Version > cfg.applied {
824				cfg.applied = rec.Version
825			}
826			return nil
827	
828		default:
829			return fmt.Errorf("unknown record type %d", recType)
830		}
831	}
832	
833	func newInstanceID() []byte {
834		id := make([]byte, 16)
835		if _, err := rand.Read(id); err != nil {
836			panic(fmt.Sprintf("cannot generate instance id: %v", err))
837		}
838		return id
839	}
840

file.content:
package fleet

import (
	"crypto/rand"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"time"
)

// Persistent mode stores every acknowledged mutation as one checksummed record
// in an append-only write-ahead log. A record is the commit unit: either the
// whole record is durable (and visible after recovery) or none of it is, so a
// replay batch can never leave half of its samples behind.
//
// Commit protocol per write (WAL frame and commit journal are separate files so
// the commit decision never depends on parsing a possibly torn frame length):
//
//  1. write the frame at the committed offset and fsync the WAL;
//  2. append a fixed-size entry carrying the new committed WAL length to the
//     commit journal and fsync it;
//  3. only then report success.
//
// Recovery reads the committed length T from the journal, verifies that WAL
// bytes [header, T) form an exact chain of valid frames, applies them, and
// treats bytes (T, EOF] as the residue of an unacknowledged write. Damage to
// committed bytes always fails startup instead of being trimmed away.

const (
	walName     = "wal.log"
	commitName  = "commit.log"
	lockName    = "lock"
	walMagic    = "EDGEFLET" // 8 bytes
	headerLen   = 16         // magic(8) + version(4) + flags(4)
	walVersion  = 1
	commitEntry = 12 // [committed WAL length uint64 LE][crc32 LE]

	// maxRecordPayload bounds a single frame; HTTP bodies are capped at 1MiB so
	// this only rejects absurd length fields from damaged files.
	maxRecordPayload = 8 << 20
)

const (
	recInstance byte = 1 + iota
	recRegister
	recTelemetry
	recReplay
	recRule
	recAlertAck
	recConfigPublish
	recConfigReceipt
)

// ErrStorageUnavailable wraps a durable-write failure at runtime. A request
// that fails this way never mutated queryable state.
var ErrStorageUnavailable = errors.New("storage unavailable")

var crcTable = crc32.MakeTable(crc32.Castagnoli)

// walSink is the commit log behind a persistent store.
type walSink interface {
	appendRecord(recType byte, value any) error
}

type walInstance struct {
	InstanceID []byte `json:"instanceId"`
}

type walRegister struct {
	ID           string    `json:"id"`
	Site         string    `json:"site"`
	RegisteredAt time.Time `json:"registeredAt"`
	LastSeenAt   time.Time `json:"lastSeenAt"`
}

type walTelemetry struct {
	DeviceID   string             `json:"deviceId"`
	Sequence   int64              `json:"sequence"`
	ObservedAt time.Time          `json:"observedAt"`
	Values     map[string]float64 `json:"values"`
	// Alerts and Ended carry the alert changes judged from this sample, in the
	// same commit unit as the sample itself. Absent in records written before
	// alerting existed.
	Alerts []*Alert `json:"alerts,omitempty"`
	Ended  []*Alert `json:"ended,omitempty"`
}

type walSample struct {
	EventID    string             `json:"eventId"`
	ObservedAt time.Time          `json:"observedAt"`
	Values     map[string]float64 `json:"values"`
}

// walReplay is one committed batch. Samples holds the full ordered batch
// (duplicates included) and Receipt the first-acceptance receipt; new events
// and their sequences are derived by zipping the two during recovery. Alerts
// and Ended carry the alert changes judged from the batch's new samples, in
// the same commit unit as the batch itself.
type walReplay struct {
	DeviceID      string             `json:"deviceId"`
	BatchID       string             `json:"batchId"`
	Samples       []walSample        `json:"samples"`
	Receipt       ReplayReceipt      `json:"receipt"`
	LastSeenAt    *time.Time         `json:"lastSeenAt,omitempty"`
	LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
	Alerts        []*Alert           `json:"alerts,omitempty"`
	Ended         []*Alert           `json:"ended,omitempty"`
}

// walRule is one committed rule create or update. Ended holds the alerts the
// update terminated with reason rule_changed, in the same commit unit.
type walRule struct {
	DeviceID string   `json:"deviceId"`
	Rule     Rule     `json:"rule"`
	Ended    []*Alert `json:"ended,omitempty"`
}

// walAlertAck is one committed alert acknowledgment.
type walAlertAck struct {
	DeviceID       string    `json:"deviceId"`
	AlertID        int64     `json:"alertId"`
	AcknowledgedAt time.Time `json:"acknowledgedAt"`
}

// walConfigPublish is one committed configuration version together with the
// requestId dedup record of its first publish.
type walConfigPublish struct {
	DeviceID    string          `json:"deviceId"`
	RequestID   string          `json:"requestId"`
	BaseVersion int64           `json:"baseVersion"`
	Version     int64           `json:"version"`
	Content     json.RawMessage `json:"content"`
	PublishedAt time.Time       `json:"publishedAt"`
}

// walConfigReceipt is one committed device application receipt.
type walConfigReceipt struct {
	DeviceID   string    `json:"deviceId"`
	ReceiptID  string    `json:"receiptId"`
	Version    int64     `json:"version"`
	Success    bool      `json:"success"`
	Reason     string    `json:"reason,omitempty"`
	ReceivedAt time.Time `json:"receivedAt"`
}

// walFile is the durable backend. walDurable is the committed WAL length (also
// the next frame offset); commitDurable is the journal length. Both files are
// truncated back to those offsets before every write, so residue left by a
// failed write can never be mistaken for later committed data.
type walFile struct {
	walF          *os.File
	commitF       *os.File
	lock          *os.File
	mu            sync.Mutex
	walDurable    int64
	commitDurable int64
}

func (w *walFile) appendRecord(recType byte, value any) error {
	frame, err := marshalFrame(recType, value)
	if err != nil {
		return err
	}
	w.mu.Lock()
	defer w.mu.Unlock()

	// Remove residue any previous failed attempt may have left, then phase 1.
	if err := w.walF.Truncate(w.walDurable); err != nil {
		return err
	}
	if err := pwriteAll(w.walF, frame, w.walDurable); err != nil {
		return err
	}
	if err := w.walF.Sync(); err != nil {
		return err
	}

	// Phase 2: publish the new committed length in the fixed-width journal.
	newLength := w.walDurable + int64(len(frame))
	entry := make([]byte, commitEntry)
	binary.LittleEndian.PutUint64(entry[0:8], uint64(newLength))
	binary.LittleEndian.PutUint32(entry[8:12], commitCRC(entry[0:8]))
	if err := w.commitF.Truncate(w.commitDurable); err != nil {
		return err
	}
	if err := pwriteAll(w.commitF, entry, w.commitDurable); err != nil {
		return err
	}
	if err := w.commitF.Sync(); err != nil {
		return err
	}

	w.walDurable = newLength
	w.commitDurable += int64(commitEntry)
	return nil
}

func commitCRC(sizeBytes []byte) uint32 {
	return crc32.Checksum(sizeBytes, crcTable)
}

func pwriteAll(f *os.File, buf []byte, offset int64) error {
	for len(buf) > 0 {
		n, err := f.WriteAt(buf, offset)
		if err != nil {
			return err
		}
		buf = buf[n:]
		offset += int64(n)
	}
	return nil
}

func (w *walFile) Close() error {
	walErr := w.walF.Close()
	commitErr := w.commitF.Close()
	// Closing the lock fd releases the flock; a killed process releases it via
	// the kernel, so no manual lock cleanup is ever required.
	lockErr := w.lock.Close()
	if walErr != nil {
		return walErr
	}
	if commitErr != nil {
		return commitErr
	}
	return lockErr
}

// NewPersistentStore opens (or creates) a data directory and finishes full
// recovery before returning. It fails rather than falling back to memory when
// the directory cannot be created, locked, read or written, when another
// process already holds the directory, or when committed data is corrupt or
// in an unsupported format.
func NewPersistentStore(dir string) (_ *Store, err error) {
	if fi, statErr := os.Stat(dir); statErr == nil {
		if !fi.IsDir() {
			return nil, fmt.Errorf("data path %s is not a directory", dir)
		}
	} else if !errors.Is(statErr, fs.ErrNotExist) {
		return nil, fmt.Errorf("cannot access data directory %s: %w", dir, statErr)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
	}

	// Take the inter-process lock before reading or writing any business data.
	lockPath := filepath.Join(dir, lockName)
	lockFile, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
	if err != nil {
		return nil, fmt.Errorf("cannot open lock file %s: %w", lockPath, err)
	}
	if lockErr := syscall.Flock(int(lockFile.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); lockErr != nil {
		_ = lockFile.Close()
		return nil, fmt.Errorf("data directory %s is already in use by another edge-fleet process: %w", dir, lockErr)
	}
	handedOff := false
	defer func() {
		if !handedOff {
			_ = lockFile.Close()
		}
	}()

	walPath := filepath.Join(dir, walName)
	commitPath := filepath.Join(dir, commitName)
	walF, err := os.OpenFile(walPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
	if err != nil {
		return nil, fmt.Errorf("cannot open write-ahead log %s: %w", walPath, err)
	}
	commitF, err := os.OpenFile(commitPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
	if err != nil {
		_ = walF.Close()
		return nil, fmt.Errorf("cannot open commit journal %s: %w", commitPath, err)
	}
	committed := false
	defer func() {
		if !committed {
			_ = walF.Close()
			_ = commitF.Close()
		}
	}()

	walInfo, err := walF.Stat()
	if err != nil {
		return nil, fmt.Errorf("cannot stat write-ahead log %s: %w", walPath, err)
	}
	if walInfo.Size() == 0 {
		if _, err := walF.WriteAt(walHeader(), 0); err != nil {
			return nil, fmt.Errorf("cannot initialise write-ahead log %s: %w", walPath, err)
		}
		if err := walF.Sync(); err != nil {
			return nil, fmt.Errorf("cannot flush write-ahead log %s: %w", walPath, err)
		}
	}

	walData, err := io.ReadAll(walF)
	if err != nil {
		return nil, fmt.Errorf("cannot read write-ahead log %s: %w", walPath, err)
	}
	commitData, err := io.ReadAll(commitF)
	if err != nil {
		return nil, fmt.Errorf("cannot read commit journal %s: %w", commitPath, err)
	}
	if len(walData) < headerLen || string(walData[0:8]) != walMagic {
		return nil, fmt.Errorf("write-ahead log %s is corrupt: bad magic header", walPath)
	}
	version := binary.LittleEndian.Uint32(walData[8:12])
	if version != walVersion {
		return nil, fmt.Errorf("write-ahead log %s uses unsupported format version %d (this server supports %d)", walPath, version, walVersion)
	}
	if binary.LittleEndian.Uint32(walData[12:16]) != 0 {
		return nil, fmt.Errorf("write-ahead log %s is corrupt: bad header flags", walPath)
	}

	// Recover the committed WAL length from the fixed-width journal. A short
	// final block is a torn append from a write that never reported success;
	// a full block with a bad CRC is committed-data damage. Entries must chain
	// strictly forward and never point past the WAL. For a fresh journal the
	// committed prefix is the header itself.
	walDurable, commitDurable := int64(headerLen), int64(0)
	for pos := 0; pos < len(commitData); pos += commitEntry {
		if len(commitData)-pos < commitEntry {
			break // torn tail: discarded by the truncate below
		}
		block := commitData[pos : pos+commitEntry]
		declared := int64(binary.LittleEndian.Uint64(block[0:8]))
		if binary.LittleEndian.Uint32(block[8:12]) != commitCRC(block[0:8]) {
			return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: bad checksum (files left untouched)", commitPath, pos)
		}
		if declared <= walDurable || declared > int64(len(walData)) || declared < headerLen {
			return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: committed length %d is inconsistent", commitPath, pos, declared)
		}
		walDurable = declared
		commitDurable = int64(pos + commitEntry)
	}

	// Every byte the journal claims committed must form an exact chain of
	// valid, in-range frames. Failure here is damage to acknowledged data.
	type parsedFrame struct {
		recType byte
		payload []byte
	}
	frames := make([]parsedFrame, 0)
	pos := headerLen
	for int64(pos) < walDurable {
		if pos+5 > len(walData) {
			return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: truncated frame inside committed prefix", walPath, pos)
		}
		length := int(binary.LittleEndian.Uint32(walData[pos : pos+4]))
		frameLen := 5 + length + 4
		if length > maxRecordPayload || int64(pos+frameLen) > walDurable {
			return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame length %d is invalid within the committed prefix", walPath, pos, length)
		}
		recType := walData[pos+4]
		payload := walData[pos+5 : pos+5+length]
		wantCRC := binary.LittleEndian.Uint32(walData[pos+5+length : pos+frameLen])
		if crc32.Checksum(walData[pos:pos+5+length], crcTable) != wantCRC {
			return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame failed its integrity check (file left untouched)", walPath, pos)
		}
		if recType < recInstance || recType > recConfigReceipt {
			return nil, fmt.Errorf("write-ahead log %s uses unsupported record type %d at byte %d", walPath, recType, pos)
		}
		frames = append(frames, parsedFrame{recType: recType, payload: payload})
		pos += frameLen
	}
	if int64(pos) != walDurable {
		return nil, fmt.Errorf("write-ahead log %s is corrupt: committed length %d is not a frame boundary", walPath, walDurable)
	}

	// Rebuild relational state from the committed frames, in order.
	store := NewStore()
	var instanceID []byte
	sawInstance := false
	for i, frame := range frames {
		switch frame.recType {
		case recInstance:
			if sawInstance || i != 0 {
				return nil, fmt.Errorf("write-ahead log %s is corrupt: instance marker out of place", walPath)
			}
			var rec walInstance
			if err := json.Unmarshal(frame.payload, &rec); err != nil || len(rec.InstanceID) == 0 || len(rec.InstanceID) > 64 {
				return nil, fmt.Errorf("write-ahead log %s is corrupt: invalid instance marker: %w", walPath, err)
			}
			instanceID = rec.InstanceID
			sawInstance = true
		case recRegister, recTelemetry, recReplay, recRule, recAlertAck, recConfigPublish, recConfigReceipt:
			if !sawInstance {
				return nil, fmt.Errorf("write-ahead log %s is corrupt: data record precedes instance marker", walPath)
			}
			if err := applyRecord(store, frame.recType, frame.payload); err != nil {
				return nil, fmt.Errorf("write-ahead log %s is corrupt: %w", walPath, err)
			}
		}
	}

	// Discard unacknowledged residue: bytes from a request that never reached
	// its journal entry (crash mid-write or a request that returned 503).
	if int64(len(walData)) != walDurable {
		if err := walF.Truncate(walDurable); err != nil {
			return nil, fmt.Errorf("cannot discard unacknowledged tail of %s: %w", walPath, err)
		}
		if err := walF.Sync(); err != nil {
			return nil, fmt.Errorf("cannot flush truncated %s: %w", walPath, err)
		}
	}
	if int64(len(commitData)) != commitDurable {
		if err := commitF.Truncate(commitDurable); err != nil {
			return nil, fmt.Errorf("cannot discard torn entry of %s: %w", commitPath, err)
		}
		if err := commitF.Sync(); err != nil {
			return nil, fmt.Errorf("cannot flush truncated %s: %w", commitPath, err)
		}
	}

	wal := &walFile{
		walF:          walF,
		commitF:       commitF,
		lock:          lockFile,
		walDurable:    walDurable,
		commitDurable: commitDurable,
	}
	if !sawInstance {
		instanceID = newInstanceID()
		if err := wal.appendRecord(recInstance, walInstance{InstanceID: instanceID}); err != nil {
			return nil, fmt.Errorf("cannot write instance marker to %s: %w", walPath, err)
		}
	}
	// Make freshly created directory entries durable as well.
	if dirFile, err := os.Open(dir); err != nil {
		return nil, fmt.Errorf("cannot open data directory %s for sync: %w", dir, err)
	} else {
		syncErr := syscall.Fsync(int(dirFile.Fd()))
		_ = dirFile.Close()
		if syncErr != nil {
			return nil, fmt.Errorf("cannot flush data directory %s: %w", dir, syncErr)
		}
	}

	store.wal = wal
	store.iid = instanceID
	committed = true
	handedOff = true
	return store, nil
}

// Close releases the WAL files and the directory lock.
func (s *Store) Close() error {
	if closer, ok := s.wal.(interface{ Close() error }); ok {
		return closer.Close()
	}
	return nil
}

func storageUnavailable(err error) error {
	return fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
}

func walHeader() []byte {
	header := make([]byte, headerLen)
	copy(header[0:8], walMagic)
	binary.LittleEndian.PutUint32(header[8:12], walVersion)
	return header
}

// marshalFrame frames one record as
// [length uint32 LE][type byte][payload][crc32 LE].
// The CRC covers length, type and payload, so even a damaged length field of
// the final frame fails verification instead of masquerading as a torn tail.
func marshalFrame(recType byte, value any) ([]byte, error) {
	payload, err := json.Marshal(value)
	if err != nil {
		return nil, err
	}
	if len(payload) > maxRecordPayload {
		return nil, fmt.Errorf("wal record too large: %d bytes", len(payload))
	}
	frame := make([]byte, 5+len(payload)+4)
	binary.LittleEndian.PutUint32(frame[0:4], uint32(len(payload)))
	frame[4] = recType
	copy(frame[5:], payload)
	binary.LittleEndian.PutUint32(frame[5+len(payload):], crc32.Checksum(frame[:5+len(payload)], crcTable))
	return frame, nil
}

// applyAlertRecord validates and applies the alert changes carried by a
// telemetry or replay record. It rejects relational inconsistency so a damaged
// WAL fails startup rather than producing broken alert state.
func applyAlertRecord(state *deviceState, created, ended []*Alert) error {
	wantID := int64(len(state.alerts)) + 1
	for _, alert := range created {
		if alert == nil {
			return errors.New("alert record contains a null create")
		}
		if alert.ID != wantID {
			return fmt.Errorf("alert create id mismatch: got %d, want %d", alert.ID, wantID)
		}
		if alert.Status != alertStatusActive || alert.RuleID == "" || alert.Metric == "" ||
			alert.TriggerSequence <= 0 || alert.TriggerObservedAt.IsZero() {
			return fmt.Errorf("alert %d create is incomplete", alert.ID)
		}
		wantID++
	}
	maxID := int64(len(state.alerts) + len(created))
	for _, alert := range ended {
		if alert == nil {
			return errors.New("alert record contains a null end")
		}
		if alert.ID < 1 || alert.ID > maxID {
			return fmt.Errorf("alert end id %d out of range (1..%d)", alert.ID, maxID)
		}
		if alert.Status != alertStatusEnded || alert.EndReason != endReasonRecovered {
			return fmt.Errorf("alert %d end is malformed", alert.ID)
		}
	}
	applyAlertChanges(state, created, ended)
	return nil
}

// applyRecord rebuilds in-memory state from one committed record, rejecting
// any structural or relational inconsistency. It never calls the clock, so
// recovery cannot refresh device timestamps.
func applyRecord(s *Store, recType byte, payload []byte) error {
	switch recType {
	case recRegister:
		var rec walRegister
		if err := json.Unmarshal(payload, &rec); err != nil {
			return fmt.Errorf("invalid register record: %w", err)
		}
		if rec.ID == "" || rec.RegisteredAt.IsZero() || rec.LastSeenAt.IsZero() {
			return errors.New("register record missing fields")
		}
		if _, exists := s.devices[rec.ID]; exists {
			return fmt.Errorf("duplicate registration for device %q", rec.ID)
		}
		s.devices[rec.ID] = &deviceState{
			device: Device{
				ID:           rec.ID,
				Site:         rec.Site,
				RegisteredAt: rec.RegisteredAt.UTC(),
				LastSeenAt:   rec.LastSeenAt.UTC(),
			},
			byEvent: make(map[string]int64),
			batches: make(map[string]storedBatch),
			rules:   make(map[string]*ruleState),
		}
		return nil

	case recTelemetry:
		var rec walTelemetry
		if err := json.Unmarshal(payload, &rec); err != nil {
			return fmt.Errorf("invalid telemetry record: %w", err)
		}
		state, ok := s.devices[rec.DeviceID]
		if !ok {
			return fmt.Errorf("telemetry for unknown device %q", rec.DeviceID)
		}
		if rec.Sequence != int64(len(state.events))+1 {
			return fmt.Errorf("device %q telemetry sequence gap: got %d, want %d", rec.DeviceID, rec.Sequence, len(state.events)+1)
		}
		if rec.ObservedAt.IsZero() || len(rec.Values) == 0 {
			return fmt.Errorf("device %q telemetry record missing fields", rec.DeviceID)
		}
		state.events = append(state.events, Event{
			Sequence:   rec.Sequence,
			ObservedAt: rec.ObservedAt.UTC(),
			Values:     cloneTelemetry(rec.Values),
		})
		state.device.LastSeenAt = rec.ObservedAt.UTC()
		state.device.LastTelemetry = cloneTelemetry(rec.Values)
		if err := applyAlertRecord(state, rec.Alerts, rec.Ended); err != nil {
			return err
		}
		return nil

	case recReplay:
		var rec walReplay
		if err := json.Unmarshal(payload, &rec); err != nil {
			return fmt.Errorf("invalid replay record: %w", err)
		}
		state, ok := s.devices[rec.DeviceID]
		if !ok {
			return fmt.Errorf("replay for unknown device %q", rec.DeviceID)
		}
		if rec.BatchID == "" || len(rec.Samples) == 0 || len(rec.Samples) != len(rec.Receipt.SampleStatus) {
			return fmt.Errorf("device %q replay record is incomplete", rec.DeviceID)
		}
		if rec.Receipt.BatchID != rec.BatchID {
			return fmt.Errorf("device %q receipt batchId %q does not match %q", rec.DeviceID, rec.Receipt.BatchID, rec.BatchID)
		}
		if _, exists := state.batches[rec.BatchID]; exists {
			return fmt.Errorf("device %q duplicate stored receipt for batch %q", rec.DeviceID, rec.BatchID)
		}

		samples := make([]Sample, len(rec.Samples))
		newCount, dupCount := 0, 0
		lastNew := -1
		for i, entry := range rec.Samples {
			status := rec.Receipt.SampleStatus[i]
			if entry.EventID == "" || entry.ObservedAt.IsZero() || len(entry.Values) == 0 {
				return fmt.Errorf("device %q batch %q sample %d is incomplete", rec.DeviceID, rec.BatchID, i)
			}
			if status.EventID != entry.EventID {
				return fmt.Errorf("device %q batch %q receipt/sample eventId mismatch at %d", rec.DeviceID, rec.BatchID, i)
			}
			samples[i] = Sample{
				EventID:    entry.EventID,
				ObservedAt: entry.ObservedAt.UTC(),
				Values:     cloneTelemetry(entry.Values),
			}
			if sequence, seen := state.byEvent[entry.EventID]; seen {
				existing := state.events[sequence-1]
				if !sameInstant(existing.ObservedAt, entry.ObservedAt) || !sameValues(existing.Values, entry.Values) {
					return fmt.Errorf("device %q dedupe record for %q disagrees with history", rec.DeviceID, entry.EventID)
				}
				if !status.Duplicate || status.Sequence != sequence {
					return fmt.Errorf("device %q receipt for %q should reuse sequence %d", rec.DeviceID, entry.EventID, sequence)
				}
				dupCount++
				continue
			}
			if status.Duplicate {
				return fmt.Errorf("device %q receipt marks unseen event %q as duplicate", rec.DeviceID, entry.EventID)
			}
			want := int64(len(state.events)) + 1
			if status.Sequence != want {
				return fmt.Errorf("device %q batch %q sequence mismatch for %q: got %d, want %d", rec.DeviceID, rec.BatchID, entry.EventID, status.Sequence, want)
			}
			state.events = append(state.events, Event{
				Sequence:   status.Sequence,
				ObservedAt: entry.ObservedAt.UTC(),
				Values:     cloneTelemetry(entry.Values),
			})
			state.byEvent[entry.EventID] = status.Sequence
			newCount++
			lastNew = i
		}
		if rec.Receipt.NewCount != newCount || rec.Receipt.Duplicate != dupCount {
			return fmt.Errorf("device %q batch %q receipt counts disagree with samples (%d/%d vs %d/%d)",
				rec.DeviceID, rec.BatchID, rec.Receipt.NewCount, rec.Receipt.Duplicate, newCount, dupCount)
		}

		if newCount > 0 {
			if rec.LastSeenAt == nil || rec.LastSeenAt.IsZero() {
				return fmt.Errorf("device %q batch %q missing recorded receive time", rec.DeviceID, rec.BatchID)
			}
			if !sameValues(rec.LastTelemetry, samples[lastNew].Values) {
				return fmt.Errorf("device %q batch %q last telemetry disagrees with last new sample", rec.DeviceID, rec.BatchID)
			}
			state.device.LastSeenAt = rec.LastSeenAt.UTC()
			state.device.LastTelemetry = cloneTelemetry(rec.LastTelemetry)
		} else if rec.LastSeenAt != nil || len(rec.LastTelemetry) != 0 {
			return fmt.Errorf("device %q all-duplicate batch %q unexpectedly refreshed device state", rec.DeviceID, rec.BatchID)
		}

		state.batches[rec.BatchID] = storedBatch{samples: samples, receipt: cloneReceipt(rec.Receipt)}
		if err := applyAlertRecord(state, rec.Alerts, rec.Ended); err != nil {
			return err
		}
		return nil

	case recRule:
		var rec walRule
		if err := json.Unmarshal(payload, &rec); err != nil {
			return fmt.Errorf("invalid rule record: %w", err)
		}
		state, ok := s.devices[rec.DeviceID]
		if !ok {
			return fmt.Errorf("rule for unknown device %q", rec.DeviceID)
		}
		if rec.Rule.ID == "" || rec.Rule.Metric == "" || rec.Rule.Version < 1 ||
			rec.Rule.CreatedAt.IsZero() || rec.Rule.UpdatedAt.IsZero() {
			return fmt.Errorf("device %q rule record is incomplete", rec.DeviceID)
		}
		if existing, exists := state.rules[rec.Rule.ID]; exists {
			if existing.rule.Version != rec.Rule.Version-1 {
				return fmt.Errorf("device %q rule %q version gap: got %d, want %d",
					rec.DeviceID, rec.Rule.ID, rec.Rule.Version, existing.rule.Version+1)
			}
			existing.rule = rec.Rule
		} else {
			if rec.Rule.Version != 1 {
				return fmt.Errorf("device %q rule %q first record has version %d, want 1",
					rec.DeviceID, rec.Rule.ID, rec.Rule.Version)
			}
			state.rules[rec.Rule.ID] = &ruleState{rule: rec.Rule}
		}
		for _, alert := range rec.Ended {
			if alert == nil || alert.ID < 1 || int(alert.ID) > len(state.alerts) {
				return fmt.Errorf("device %q rule %q ends unknown alert", rec.DeviceID, rec.Rule.ID)
			}
			if alert.Status != alertStatusEnded || alert.EndReason != endReasonRuleChanged || alert.EndedAt == nil {
				return fmt.Errorf("device %q rule %q end of alert %d is malformed", rec.DeviceID, rec.Rule.ID, alert.ID)
			}
			state.alerts[alert.ID-1] = alert
			if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
				rs.activeAlertID = 0
			}
		}
		return nil

	case recAlertAck:
		var rec walAlertAck
		if err := json.Unmarshal(payload, &rec); err != nil {
			return fmt.Errorf("invalid alert ack record: %w", err)
		}
		state, ok := s.devices[rec.DeviceID]
		if !ok {
			return fmt.Errorf("alert ack for unknown device %q", rec.DeviceID)
		}
		if rec.AlertID < 1 || int(rec.AlertID) > len(state.alerts) {
			return fmt.Errorf("device %q ack for unknown alert %d", rec.DeviceID, rec.AlertID)
		}
		if rec.AcknowledgedAt.IsZero() {
			return fmt.Errorf("device %q ack for alert %d missing time", rec.DeviceID, rec.AlertID)
		}
		alert := state.alerts[rec.AlertID-1]
		if alert.AcknowledgedAt == nil {
			t := rec.AcknowledgedAt.UTC()
			alert.AcknowledgedAt = &t
		}
		return nil

	case recConfigPublish:
		var rec walConfigPublish
		if err := json.Unmarshal(payload, &rec); err != nil {
			return fmt.Errorf("invalid config publish record: %w", err)
		}
		state, ok := s.devices[rec.DeviceID]
		if !ok {
			return fmt.Errorf("config publish for unknown device %q", rec.DeviceID)
		}
		if rec.RequestID == "" || rec.PublishedAt.IsZero() {
			return fmt.Errorf("device %q config publish record is incomplete", rec.DeviceID)
		}
		if !isNonEmptyJSONObject(rec.Content) {
			return fmt.Errorf("device %q config v%d content is not a non-empty JSON object", rec.DeviceID, rec.Version)
		}
		if state.config == nil {
			state.config = newConfigState()
		}
		cfg := state.config
		if rec.Version != int64(len(cfg.versions))+1 {
			return fmt.Errorf("device %q config version gap: got %d, want %d",
				rec.DeviceID, rec.Version, len(cfg.versions)+1)
		}
		if rec.BaseVersion != rec.Version-1 {
			return fmt.Errorf("device %q config v%d base %d does not precede version",
				rec.DeviceID, rec.Version, rec.BaseVersion)
		}
		if _, dup := cfg.publishes[rec.RequestID]; dup {
			return fmt.Errorf("device %q duplicate config publish request %q", rec.DeviceID, rec.RequestID)
		}
		if rec.Version <= cfg.applied {
			return fmt.Errorf("device %q config v%d published after applied %d", rec.DeviceID, rec.Version, cfg.applied)
		}
		content := cloneJSON(rec.Content)
		cfg.versions = append(cfg.versions, publishedConfig{
			content:     content,
			publishedAt: rec.PublishedAt.UTC(),
		})
		cfg.publishes[rec.RequestID] = storedPublish{
			baseVersion: rec.BaseVersion,
			content:     cloneJSON(content),
			result: ConfigPublishResult{
				RequestID:   rec.RequestID,
				Version:     rec.Version,
				Content:     cloneJSON(content),
				PublishedAt: rec.PublishedAt.UTC(),
			},
		}
		return nil

	case recConfigReceipt:
		var rec walConfigReceipt
		if err := json.Unmarshal(payload, &rec); err != nil {
			return fmt.Errorf("invalid config receipt record: %w", err)
		}
		state, ok := s.devices[rec.DeviceID]
		if !ok {
			return fmt.Errorf("config receipt for unknown device %q", rec.DeviceID)
		}
		if rec.ReceiptID == "" || rec.ReceivedAt.IsZero() {
			return fmt.Errorf("device %q config receipt record is incomplete", rec.DeviceID)
		}
		if !rec.Success && strings.TrimSpace(rec.Reason) == "" {
			return fmt.Errorf("device %q config receipt %q fails without a reason", rec.DeviceID, rec.ReceiptID)
		}
		if state.config == nil {
			state.config = newConfigState()
		}
		cfg := state.config
		if rec.Version < 1 || rec.Version > int64(len(cfg.versions)) {
			return fmt.Errorf("device %q config receipt %q for unknown version %d", rec.DeviceID, rec.ReceiptID, rec.Version)
		}
		if _, dup := cfg.byReceipt[rec.ReceiptID]; dup {
			return fmt.Errorf("device %q duplicate config receipt %q", rec.DeviceID, rec.ReceiptID)
		}
		if rec.Version < cfg.applied {
			return fmt.Errorf("device %q config receipt %q version %d is below applied %d",
				rec.DeviceID, rec.ReceiptID, rec.Version, cfg.applied)
		}
		if !rec.Success && rec.Version <= cfg.applied {
			return fmt.Errorf("device %q config receipt %q fails an already applied version %d",
				rec.DeviceID, rec.ReceiptID, rec.Version)
		}
		receipt := ConfigReceipt{
			ReceiptID:  rec.ReceiptID,
			Version:    rec.Version,
			Success:    rec.Success,
			Reason:     rec.Reason,
			ReceivedAt: rec.ReceivedAt.UTC(),
		}
		cfg.receipts = append(cfg.receipts, receipt)
		cfg.byReceipt[rec.ReceiptID] = receipt
		if rec.Success && rec.Version > cfg.applied {
			cfg.applied = rec.Version
		}
		return nil

	default:
		return fmt.Errorf("unknown record type %d", recType)
	}
}

func newInstanceID() []byte {
	id := make([]byte, 16)
	if _, err := rand.Read(id); err != nil {
		panic(fmt.Sprintf("cannot generate instance id: %v", err))
	}
	return id
}

