package fleet

import (
	"encoding/json"
	"errors"
	"time"
)

// Remote diagnostics lets a fleet operator create tasks for a registered
// device; a simulated device claims the oldest claimable task, runs it for the
// requested number of seconds, and reports a JSON result or a failure.
//
// Lifecycle:
//
//	pending -> claimed/running -> succeeded / failed
//	             (on failure)   -> waiting -> claimed ... -> failed(terminal on 3rd)
//	pending/waiting/running -> cancelled
//
// An in-flight attempt that passes its deadline counts as a timeout failure.
// Failures invalidate the claim token, free the device's single execution
// slot, and arm a retry backoff (1s after the first failure, 2s after the
// second); the third failure ends the task. Cancellation ends immediately and
// invalidates any outstanding token.

const (
	taskStatusPending   = "pending"
	taskStatusRunning   = "running"
	taskStatusWaiting   = "waiting"
	taskStatusSucceeded = "succeeded"
	taskStatusFailed    = "failed"
	taskStatusCancelled = "cancelled"

	// auditActionClaim etc.
	auditActionCreate  = "create"
	auditActionClaim   = "claim"
	auditActionFail    = "fail"
	auditActionTimeout = "timeout"
	auditActionSuccess = "success"
	auditActionCancel  = "cancel"

	maxTaskAttempts = 3
)

var (
	// ErrTaskConflict covers a requestId reused with changed seconds, a report
	// whose receiptId was already used with different content, a report using
	// an invalid/unknown/foreign/expired token, and cancelling or reporting on
	// a task already finished by success or failure.
	ErrTaskConflict = errors.New("diagnostic task conflict")
	// ErrTaskNotFound is returned for an unknown task number on a known device.
	ErrTaskNotFound = errors.New("diagnostic task not found")
)

// retryDelays[failures-so-far] is the wait before the task may be claimed
// again: 1s after the first failure, 2s after the second.
var retryDelays = map[int]time.Duration{
	1: time.Second,
	2: 2 * time.Second,
}

// TaskSummary is the external view of one diagnostic task.
type TaskSummary struct {
	Number           int64           `json:"number"`
	RequestID        string          `json:"requestId"`
	Seconds          int             `json:"seconds"`
	Status           string          `json:"status"`
	Attempts         int             `json:"attempts"`
	CreatedAt        time.Time       `json:"createdAt"`
	ClaimedAt        *time.Time      `json:"claimedAt,omitempty"`
	Deadline         *time.Time      `json:"deadline,omitempty"`
	NextClaimableAt  *time.Time      `json:"nextClaimableAt,omitempty"`
	FinalAttempt     int             `json:"finalAttempt,omitempty" json:"-"`
	FinishedAt       *time.Time      `json:"finishedAt,omitempty"`
	Result           json.RawMessage `json:"result,omitempty"`
	FailureReason    string          `json:"failureReason,omitempty"`
	FinalReceiptID   string          `json:"-"`
	FinalReportAt    *time.Time      `json:"-"`
	CancelResult     *TaskCancellation `json:"-"`
}

// TaskClaimView is returned on a successful claim.
type TaskClaimView struct {
	Task     int64     `json:"task"`
	Attempt  int      `json:"attempt"`
	Token    string   `json:"token"`
	Deadline time.Time `json:"deadline"`
	Seconds  int      `json:"seconds"`
}

// TaskCancellation is stored (and returned on repeated cancellation) when an
// operator cancels a live task.
type TaskCancellation struct {
	Task       int64     `json:"task"`
	Status     string    `json:"status"`
	CancelledAt time.Time `json:"cancelledAt"`
}

// AuditEntry records one state transition with before/after status and the
// attempt it happened on. Retries and rejections never create entries.
type AuditEntry struct {
	Seq        int       `json:"seq"`
	Task       int64     `json:"task"`
	Action     string    `json:"action"`
	FromStatus string    `json:"fromStatus"`
	ToStatus   string    `json:"toStatus"`
	Attempt    int       `json:"attempt"`
	At         time.Time `json:"at" json:"at"`
	Reason     string    `json:"reason,omitempty"`
}

// attemptState describes the outcome of claim/timeout processing so the
// transition can be recorded in one commit unit with the claim itself.
type attemptOutcome struct {
	action   string
	from, to string
	reason   string
	at       time.Time
}

// taskAttempt is one claim: the token handed out, its attempt number (1-based
// per task), the deadline, and whether it has been used by an accepted report
// or invalidated by failure/timeout/cancel.
//
// Old attempts are retained: a report arriving with the previous token after
// a failover must be rejected as foreign to the current attempt, not accepted
// as an unknown token.
type taskAttempt struct {
	num      int
	token    string
	deadline time.Time
	claimedAt time.Time
	used     bool   // an accepted report consumed this attempt
	invalid  bool   // failure/timeout/cancel invalidated this attempt
	timeoutRecorded bool // its timeout transition was already recorded

}

// taskData is the full state of one diagnostic task.
type taskData struct {
	deviceID     string
	number       int64
	requestID    string
	seconds      int
	status       string
	attempts     int
	createdAt    time.Time
	claiming     bool // transient: claimed but not yet made durable (persistent mode only)
	claimedAt    *time.Time
	deadline     *time.Time
	nextClaim    time.Time // waiting: earliest re-claim; pending tasks claim immediately
	history      []taskAttempt
	// terminal payloads
	result       json.RawMessage
	reason       string
	finishedAt   *time.Time
	finalReport  *storedTaskReport
	// cancellation idempotency
	cancelledBy  string
	cancelAt     *time.Time
	#warning

	resultJSON   json.RawMessage
}

// storedTaskReport remembers the first accepted report of a terminal report
// so a re-POST with the same receiptId returns 200 even after the task ends.
type storedTaskReport struct {
	receiptID string
	at        time.Time
	view      TaskReportAck
}

// TaskReportAck is the response body for an accepted report or a matching
// retry.
type TaskReportAck struct {
	Task     int64           `json:"task"`
	Attempt  int            `json:"-"`
	Status   string         `json:"status"`
	Attempts int            `json:"attempts"`
	ReceiptID string         `json:"receiptId"`
	ReceivedAt time.Time     `json:"receivedAt" json:"receivedAt"`
	Result   json.RawMessage `json:"result,omitempty"`
	Reason   string         `json:"reason,omitempty"`
}

// diagnosticsState holds all diagnostic tasks for one device.
type diagnosticsState struct {
	tasks         []*taskData            // number = index + 1
	byRequest     map[string]*taskData   // requestId -> task
	byToken       map[string]tokenRef    // token -> (task, attempt)
	activeTask    int64                  // number of the running task, 0 when slot free
	audit         []AuditEntry           // global per-device audit order
}

type tokenRef struct {
	number  int64
	attempt int
}

func newDiagnosticsState() *diagnosticsState {
	return &diagnosticsState{
		byRequest: make(map[string]*taskData),
		byToken:   make(map[string]tokenRef),
	}
}

// --- helpers used while holding the store lock -----------------------------

// settleExpired marks timed-out attempts (and tasks that end on their third
// failure) according to the current clock. Returns the transitions produced
// (claim->timeout, waiting->fail...) so they can be committed together.
func (d *diagnosticsState) settleExpired(now time.Time) []attemptOutcome {
	var transitions []attemptOutcome
	if d.activeTask != 0 {
		task := d.tasks[d.activeTask-1]
		if task.status == taskStatusRunning {
			last := task.history[len(task.history)-1]
			if !last.used && !last.invalid && !now.Before(last.deadline) {
				transitions = append(transitions, task.applyTimeout(now))
				d.activeTask = 0
				if task.status == taskStatusRunning {
					// Defensive: applyTimeout must move it out of running.
					d.activeTask = task.number
				}
			}

		}
	}
	return transitions
}

// applyTimeout treats the current attempt as failed by deadline. It records
// the claim->timeout audit entry and then the same failure bookkeeping an
// explicit failure report would produce (backoff or terminal failure).
func (t *taskData) applyTimeout(now time.Time) attemptOutcome {
	attempt := t.history[len(t.history)-1]
	attempt.invalid = true
	attempt.timeoutRecorded = true
	t.history[len(t.history)-1] = attempt
	t.attempts++
	outcome := attemptOutcome{
		action: auditActionTimeout,
		from:   taskStatusRunning,
		to:     "",
		at:     now,
		reason: "execution deadline exceeded",
	}
	if t.attempts >= maxTaskAttempts {
		t.status = taskStatusFailed
		t.reason = outcome.reason
		finished := now
		t.finishedAt = &finished
		outcome.to = taskStatusFailed
	} else {
		t.status = taskStatusWaiting
		t.nextClaim = now.Add(retryDelays[t.attempts])
		t.deadline = nil
		outcome.to = taskStatusWaiting
	}
	return outcome
}

// applyFailure handles a device-reported failure for attempt n.
func (t *taskData) applyFailure(now time.Time, reason string) attemptOutcome {
	attempt := t.history[len(t.history)-1]
	attempt.invalid = true
	t.history[len(t.history)-1] = attempt
	t.attempts++
	outcome := attemptOutcome{
		action: auditActionFail,
		from:   taskStatusRunning,
		to:     "",
		at:     now,
		reason: reason,
	}
	if t.attempts >= maxTaskAttempts {
		t.status = taskStatusFailed
		t.reason = reason
		finished := now
		t.finishedAt = &finished
		outcome.to = taskStatusFailed
	} else {
		t.status = taskStatusWaiting
		t.nextClaim = now.Add(retryDelays[t.attempts])
		t.deadline = nil
		outcome.to = taskStatusWaiting
	}
	return outcome
}

// applySuccess ends the task successfully on the current attempt.
func (t *taskData) applySuccess(now time.Time, result json.RawMessage) attemptOutcome {
	attempt := t.history[len(t.history)-1]
	attempt.used = true
	t.history[len(t.history)-1] = attempt
	t.status = taskStatusSucceeded
	t.result = cloneJSON(result)
	t.reason = ""
	finished := now
	t.finishedAt = &finished
	return attemptOutcome{
		action: auditActionSuccess,
		from:   taskStatusRunning,
		to:     taskStatusSucceeded,
		at:     now,
	}
}

// claimable reports whether the task may be claimed at now: pending claims
// immediately, waiting tasks only after their backoff instant, anything else
// never.
func (t *taskData) claimable(now time.Time) bool {
	switch t.status {
	case taskStatusPending:
		return true
	case taskStatusWaiting:
		return !now.Before(t.nextClaim)
	}
	return false
}

// --- Store API -------------------------------------------------------------

// CreateDiagnosticTask creates a pending task. requestId dedups within the
// device: identical re-submission returns the first result (repeat=true,
// 200), changed duration is ErrTaskConflict (409).
func (s *Store) CreateDiagnosticTask(deviceID, requestID string, seconds int) (TaskSummary, bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, ok := s.devices[deviceID]
	if !ok {
		return TaskSummary{}, false, ErrDeviceNotFound
	}
	d := state.ensureDiagnostics()
	now := s.now().UTC()

	if previous, seen := d.byRequest[requestID]; seen {
		if previous.seconds != seconds {
			return TaskSummary{}, false, ErrTaskConflict
		}
		return s.taskView(previous, now), true, nil
	}

	task := &taskData{
		deviceID:  deviceID,
		number:    int64(len(d.tasks)) + 1,
		requestID: requestID,
		seconds:   seconds,
		status:    taskStatusPending,
		createdAt: now,
	}
	if s.wal != nil {
		if err := s.wal.appendRecord(recTaskCreate, walTaskCreate{
			DeviceID:  deviceID,
			Number:    task.number,
			RequestID: requestID,
			Seconds:   seconds,
			CreatedAt: now,
		}); err != nil {
			return TaskSummary{}, false, storageUnavailable(err)
		}
	}
	d.tasks = append(d.tasks, task)
	d.byRequest[requestID] = task
	d.appendAudit(task, attemptOutcome{
		action: auditActionCreate,
		from:   "",
		to:     taskStatusPending,
		at:     now,
	})
	return s.taskView(task, now), false, nil
}

// ClaimDiagnosticTask hands out the oldest claimable task. There is at most
// one running task per device even under concurrent callers; when nothing is
// claimable (including after settling timeouts/backoffs) it returns ok=false
// for a 204.
func (s *Store) ClaimDiagnosticTask(deviceID string) (TaskClaimView, bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, ok := s.devices[deviceID]
	if !ok {
		return TaskClaimView{}, false, ErrDeviceNotFound
	}
	d := state.ensureDiagnostics()
	now := s.now().UTC()

	// A deadline that elapsed without a report counts as a failure before
	// anything else can be claimed.
	transitions := d.settleExpired(now)

	if d.activeTask != 0 {
		return TaskClaimView{}, false, nil
	}
	var target *taskData
	for _, task := range d.tasks {
		if task.claimable(now) {
			target = task
			break
		}
	}
	if target == nil {
		// Persist any timeout transitions produced even though nothing new is
		// being claimed, so state and audit survive a crash immediately after.
		if err := s.persistTaskTransitions(deviceID, d, transitions, nil); err != nil {
			return TaskClaimView{}, false, err
		}
		return TaskClaimView{}, false, nil
	}

	attemptNum := target.attempts + 1
	token := newTaskToken()
	deadline := now.Add(time.Duration(target.seconds) * time.Second)
	attempt := taskAttempt{
		num:       attemptNum,
		token:     token,
		deadline: deadline,
		claimedAt: now,
	}
	target.status = taskStatusRunning
	target.attempts = attemptNum
	target.claimedAt = &now
	target.deadline = &deadline
	target.history = append(target.history, attempt)
	d.activeTask = target.number
	d.byToken[token] = tokenRef{number: target.number, attempt: attemptNum}
	transition := attemptOutcome{
		action: auditActionClaim,
		from:   targetBeforeStatus(target, 1),
		to:     taskStatusRunning,
		at:     now,
	}
	// Wait: the token is queryable only after the durable append succeeds.
	if s.wal != nil {
		if err := s.wal.appendRecord(recTaskClaim, walTaskClaim{
			DeviceID:  deviceID,
			Number:    target.number,
			Attempt:   attemptNum,
			Token:     token,
			Seconds:   target.seconds,
			ClaimedAt: now,
			Deadline:  deadline,
		}); err != nil {
			// Roll back the in-memory claim immediately; no audit row was added.
			rollbackClaim(d, target, attemptNum, now)
			return TaskClaimView{}, false, storageUnavailable(err)
		}
	}
	// Commit transitions: the claim row follows any timeout settled above.
	for _, tr := range transitions {
		d.appendAudit(d.tasks[tr.taskNumber()], tr)
	}
	d.appendAudit(target, transition)
	return TaskClaimView{
		Task:     target.number,
		Attempt:  attemptNum,
		Token:    token,
		Deadline: deadline,
		Seconds:  target.seconds,
	}, true, nil
}

// ReportDiagnosticTask accepts the simulated device's outcome for an attempt.
//
// Validation order:
//  1. device/task existence
//  2. receiptId dedup within the task
//  3. token validity (known, current attempt, unexpired)
//  4. the task must still be running this attempt
//
// A matching receiptId retry returns the first ack (repeat=true, 200) even
// after the task ends; a reused receiptId with different content is 409.
//
// On the third failure or a success, audit rows and state are one commit
// unit. A report arriving exactly at/after the deadline is 409.
func (s *Store) ReportDiagnosticTask(deviceID, token, receiptID string, success bool, reason string, result json.RawMessage) (TaskReportAck, bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, ok := s.devices[deviceID]
	if !ok {
		return TaskReportAck{}, false, ErrDeviceNotFound
	}
	d := state.ensureDiagnostics()
	now := s.now().UTC()

	ref, tokenKnown := d.byToken[token]
	var task *taskData
	// We need the task for receiptId dedup even when the token is garbage;
	// resolve it via the token when possible.
	if tokenKnown {
		task = d.tasks[ref.number-1]
	} else {
		// An unknown token carries no task reference; dedup cannot be located.
		// Spec: invalid/unknown token -> 409 regardless.
		return TaskReportAck{}, false, ErrTaskConflict
	}
	if ref.attempt != len(task.history) ||
		task.history[ref.attempt-1].invalid ||
		task.history[ref.attempt-1].used {
		// Expired, superseded or already-consumed token.
		return TaskReportAck{}, false, ErrTaskConflict
	}
	attempt := task.history[ref.attempt-1]
	if !now.Before(attempt.deadline) {
		return TaskReportAck{}, false, ErrTaskConflict
	}
	if task.status != taskStatusRunning || d.activeTask != task.number {
		return TaskReportAck{}, false, ErrTaskConflict
	}

	// receiptId dedup within the task.
	if previous, seen := task.finalReport; seen {
		same := previous.receiptID == receiptID &&
			previous.view.Status == terminalFor(success) &&
			previous.view.Reason == reason
		if !same {
			return TaskReportAck{}, false, ErrTaskConflict
		}
		// A matching retry: the stored ack carries the original time.
		return previous.view, true, nil
	}

	var transition attemptOutcome
	var ack TaskReportAck
	if success {
		transition = task.applySuccess(now, result)
		ack = TaskReportAck{
			Task:       task.number,
			Status:     taskStatusSucceeded,
			Attempts:   task.attempts,
			ReceiptID: receiptID,
			ReceivedAt: now,
			Result:     cloneJSON(result),
		}
	} else {
		transition = task.applyFailure(now, reason)
		attempt = task.history[len(task.history)-1]
		ack = TaskReportAck{
			Task:       task.number,
			Status:     task.status,
			Attempts:   task.attempts,
			ReceiptID: receiptID,
			ReceivedAt: now,
			Reason:     reason,
		}
	}

	if s.wal != nil {
		record := walTaskReport{
			DeviceID:  deviceID,
			Number:    task.number,
			Attempt:   attempt.num,
			Token:     attempt.token,
			ReceiptID: receiptID,
			Success:   success,
			Reason:    reason,
			Result:    cloneJSON(result),
			At:        now,
		}
		if err := s.wal.appendRecord(recTaskReport, record); err != nil {
			rollbackReport(d, task, transition, attempt, now)
			return TaskReportAck{}, false, storageUnavailable(err)
		}
	}

	d.activeTask = 0
	removeCurrentToken(d, task)
	if success || task.status == taskStatusFailed {
		// Terminal: remember the first accepted report for idempotent retries.
		task.finalReport = &storedTaskReport{
			receiptID: receiptID,
			at:        now,
			view:      cloneReportAck(ack),
		}
	} else {
		// Non-terminal failure: old token is invalid; device must re-claim.
		// Keep the attempt in history (it carries the backoff trigger).
	}
	d.appendAudit(task, transition)
	return ack, false, nil
}

// CancelDiagnosticTask cancels a pending, waiting or running task. Repeated
// cancellation returns the first result (repeat=true). Cancelling a task
// already ended by success or failure is 409.
func (s *Store) CancelDiagnosticTask(deviceID string, number int64) (TaskCancellation, bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, ok := s.devices[deviceID]
	if !ok {
		return TaskCancellation{}, false, ErrDeviceNotFound
	}
	d := state.ensureDiagnostics()
	now := s.now().UTC()

	transitions := d.settleExpired(now)
	task, err := d.taskByNumber(number)
	if err != nil {
		return TaskCancellation{}, false, err
	}
	if task.cancelAt != nil {
		return TaskCancellation{
			Task:        task.number,
			Status:      taskStatusCancelled,
			CancelledAt: *task.cancelAt,
		}, true, nil
	}
	if task.terminal() {
		return TaskCancellation{}, false, ErrTaskConflict
	}

	from := task.status
	task.status = taskStatusCancelled
	task.nextClaim = time.Time{}
	task.deadline = nil
	if d.activeTask == task.number {
		d.activeTask = 0
		removeCurrentToken(d, task)
	}
	for i := range task.history {
		task.history[i].invalid = true
	}
	cancelledAt := now
	task.cancelAt = &cancelledAt
	task.finishedAt = &cancelledAt
	transition := attemptOutcome{
		action: auditActionCancel,
		from:   from,
		to:     taskStatusCancelled,
		at:     now,
	}
	if s.wal != nil {
		record := walTaskCancel{
			DeviceID:    deviceID,
			Number:      task.number,
			Attempt:     task.attempts,
			FromStatus:  from,
			CancelledAt: now,
		}
		if err := s.wal.appendRecord(recTaskCancel, record); err != nil {
			rollbackCancel(d, task, transitions, from, now)
			return TaskCancellation{}, false, storageUnavailable(err)
		}
	}
	for _, tr := range transitions {
		d.appendAudit(d.tasks[tr.taskNumber()], tr)
	}
	d.appendAudit(task, transition)
	return TaskCancellation{
		Task:        task.number,
		Status:      taskStatusCancelled,
		CancelledAt: now,
	}, false, nil
}

// ListDiagnosticTasks returns a device's tasks in number order, settling
// elapsed deadlines first so queries reflect expired attempts.
func (s *Store) ListDiagnosticTasks(deviceID string) ([]TaskSummary, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, ok := s.devices[deviceID]
	if !ok {
		return nil, ErrDeviceNotFound
	}
	d := state.ensureDiagnostics()
	now := s.now().UTC()
	transitions := d.settleExpired(now)
	if err := s.persistTaskTransitions(deviceID, d, transitions, nil); err != nil {
		return nil, err
	}
	result := make([]TaskSummary, 0, len(d.tasks))
	for _, task := range d.tasks {
		result = append(result, s.taskView(task, now))
	}
	return result, nil
}

// GetDiagnosticTask returns one task.
func (s *Store) GetDiagnosticTask(deviceID string, number int64) (TaskSummary, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, ok := s.devices[deviceID]
	if !ok {
		return TaskSummary{}, ErrDeviceNotFound
	}
	d := state.ensureDiagnostics()
	now := s.now().UTC()
	transitions := d.settleExpired(now)
	if err := s.persistTaskTransitions(deviceID, d, transitions, nil); err != nil {
		return TaskSummary{}, err
	}
	task, err := d.taskByNumber(number)
	if err != nil {
		return TaskSummary{}, err
	}
	return s.taskView(task, now), nil
}

// ListTaskAudit returns audit entries in occurrence order.
func (s *Store) ListTaskAudit(deviceID string) ([]AuditEntry, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	state, ok := s.devices[deviceID]
	if !ok {
		return nil, ErrDeviceNotFound
	}
	d := state.ensureDiagnostics()
	now := s.now().UTC()
	transitions := d.settleExpired(now)
	if err := s.persistTaskTransitions(deviceID, d, transitions, nil); err != nil {
		return nil, err
	}
	return append([]AuditEntry(nil), d.audit...), nil
}

// --- small helpers ----------------------------------------------------------

func (d *diagnosticsState) taskByNumber(number int64) (*taskData, error) {
	if number < 1 || int(number) > len(d.tasks) {
		return nil, ErrTaskNotFound
	}
	return d.tasks[number-1], nil
}

func (t *taskData) terminal() bool {
	switch t.status {
	case taskStatusSucceeded, taskStatusFailed, taskStatusCancelled:
		return true
	}
	return false
}

func terminalFor(success bool) string {
	if success {
		return taskStatusSucceeded
	}
	return taskStatusFailed
}

// taskView renders the external summary. It does not leak tokens; the
// NextClaimableAt pointer is set for waiting tasks.
func (s *Store) taskView(t *taskData, now time.Time) TaskSummary {
	view := TaskSummary{
		Number:     t.number,
		RequestID:  t.requestID,
		Seconds:    t.seconds,
		Status:     t.status,
		Attempts:   t.attempts,
		CreatedAt:  t.createdAt,
		ClaimedAt:  cloneTimePtr(t.claimedAt),
		Deadline:   cloneTimePtr(t.deadline),
		FinishedAt: cloneTimePtr(t.finishedAt),
		Result:     cloneJSON(t.result),
		FailureReason: t.reason,
	}
	if t.status == taskStatusWaiting {
		nc := t.nextClaim.UTC()
		view.NextClaimableAt = &nc
	}
	return view
}

// persistTaskTransitions writes transitions produced by timeout settling
// (claim->timeout and possibly timeout->fail) as a single WAL record. In
// memory mode it is a no-op. The audit rows are appended to state only after
// the durable write succeeds.
func (s *Store) persistTaskTransitions(deviceID string, d *diagnosticsState, transitions []attemptOutcome, extra []attemptOutcome) error {
	if s.wal == nil || len(transitions) == 0 {
		return nil
	}
	entries := make([]walTaskTransition, 0, len(transitions)+len(extra))
	for _, tr := range transitions {
		entries = append(entries, walTaskTransition{
			Number:   tr.taskNumber(),
			Action:   tr.action,
			From:     tr.from,
			To:       tr.to,
			Attempt:  tr.attempt,
			At:       tr.at,
			Reason:   tr.reason,
		})
	}
	for _, tr := range extra {
		entries = append(entries, walTaskTransition{
			Number:   tr.taskNumber(),
			Action:   tr.action,
			From:     tr.from,
			To:             tr.to,
			Attempt:  tr.attempt,
			At:       tr.at,
			Reason:   tr.reason,
		})
	}
	if err := s.wal.appendRecord(recTaskTransition, walTaskTransitions{
		DeviceID:    deviceID,
		Transitions: entries,
	}); err != nil {
		// The clock-derived state change is not made durable; keep in-memory
		// state as-is (it will simply be re-derived on the next call). The
		// caller's own mutation (claim/report/cancel) must roll itself back.
		return storageUnavailable(err)
	}
	for _, tr := range transitions {
		d.appendAudit(d.tasks[tr.taskNumber()-1], tr)
	}
	return nil
}

// appendAudit appends one audit row for a task transition.
func (d *diagnosticsState) appendAudit(t *taskData, tr attemptOutcome) {
	d.audit = append(d.audit, AuditEntry{
		Seq:        len(d.audit) + 1,
		Task:       t.number,
		Action:     tr.action,
		FromStatus: tr.from,
		ToStatus:   tr.to,
		Attempt:    tr.attempt,
		At:         tr.at.UTC(),
		Reason:     tr.reason,
	})
}

func cloneTimePtr(t *time.Time) *time.Time {
	if t == nil {
		return nil
	}
	c := t.UTC()
	return &c
}

func cloneReportAck(a TaskReportAck) TaskReportAck {
	a.Result = cloneJSON(a.Result)
	return a
}

func removeCurrentToken(d *diagnosticsState, t *taskData) {
	if len(t.history) == 0 {
		return
	}
	delete(d.byToken, t.history[len(t.history)-1].token)
}

// taskNumber satisfies the transition carrier.
func (o attemptOutcome) taskNumber() int64 { return o.number }

// targetBeforeStatus returns the status a task had before the given claim
// attempt (pending for attempt 1, waiting otherwise).
func targetBeforeStatus(t *taskData, attempt int) string {
	if attempt <= 1 {
		return taskStatusPending
	}
	return taskStatusWaiting
}

// rollbackClaim undoes a claim whose WAL append failed.
func rollbackClaim(d *diagnosticsState, t *taskData, attemptNum int, now time.Time) {
	t.status = taskStatusWaiting
	if attemptNum <= 1 {
		t.status = taskStatusPending
	}
	t.attempts = attemptNum - 1
	t.history = t.history[:len(t.history)-1]
	t.deadline = nil
	if attemptNum == 1 {
		t.claimedAt = nil
	}
	d.activeTask = 0
	delete(d.byToken, "")
}

// rollbackReport undoes a report whose WAL append failed.
func rollbackReport(d *diagnosticsState, t *taskData, tr attemptOutcome, current taskAttempt, now time.Time) {
	if tr.action == auditActionSuccess {
		t.status = taskStatusRunning
		t.result = nil
		t.finishedAt = nil
		last := t.history[len(t.history)-1]
		last.used = false
		t.history[len(t.history)-1] = last
	} else {
		t.status = taskStatusRunning
		t.reason = ""
		t.finishedAt = nil
		// Restore the deadline that applyFailure cleared.
		deadline := current.deadline
		t.deadline = &deadline
		last := t.history[len(t.history)-1]
		last.invalid = false
		t.history[len(t.history)-1] = last
		t.attempts--
		// activeTask and token were not yet touched; nothing else to undo.
	}
	if d.activeTask != t.number {
		d.activeTask = t.number
	}
}

// rollbackCancel undoes a cancel whose WAL append failed.
func rollbackCancel(d *diagnosticsState, t *taskData, settled []attemptOutcome, from string, now time.Time) {
	t.status = from
	t.cancelAt = nil
	t.finishedAt = nil
	t.nextClaim = settledNextClaim(t, settled)
	if from == taskStatusRunning {
		d.activeTask = t.number
		last := t.history[len(t.history)-1]
		last.invalid = false
		t.history[len(t.history)-1] = last
		t.deadline = &last.deadline
		d.byToken[last.token] = tokenRef{number: t.number, attempt: last.num}
	}
}

func settledNextClaim(t *taskData, settled []attemptOutcome) time.Time {
	for _, tr := range settled {
		if tr.taskNumber() == t.number && tr.to == taskStatusWaiting {
			return tr.at.Add(retryDelays[tr.attempt])
		}
	}
	return time.Time{}
}

