	r = doRequest(t, h, http.MethodGet,
		fmt.Sprintf("/v1/devices/%s/diagnostic-tasks/1", diagDevice), "")
	detail := decodeBody[TaskSummary](t, r)
	if detail.Status != taskStatusSucceeded || string(detail.Result) == "" {
		t.Fatalf("detail = %+v", detail)
	}
}

